function initCellAtlas() {
  const svg = document.getElementById('cellAtlasSvg');
  const panel = document.getElementById('atlasPanel');
  if (!svg || !panel) return;

  const renderPanel = (id) => {
    const d = ATLAS_DATA[id];
    if (!d) return;
    panel.innerHTML = `
      <div class="atlas-detail">
        <div class="atlas-lbl">Organelle</div>
        <h4>${d.name}</h4>
        <div class="atlas-row"><div class="atlas-row-lbl">Function</div><p>${d.func}</p></div>
        <div class="atlas-row"><div class="atlas-row-lbl">Detail</div><p>${d.sub}</p></div>
        <div class="atlas-row"><div class="atlas-row-lbl">On the DAT</div><p>${d.dat}</p></div>
        <a class="atlas-link" href="#${d.deepDive}">Deep-dive &middot; ${d.diveLabel}</a>
      </div>
    `;
  };

  svg.querySelectorAll('.organelle').forEach(el => {
    el.addEventListener('click', () => {
      const id = el.dataset.organelle;
      svg.querySelectorAll('.organelle').forEach(o => o.classList.remove('active'));
      el.classList.add('active');
      svg.classList.add('has-active');
      renderPanel(id);
    });
  });

  // View toggle (animal / plant / prokaryote)
  const ctrl = document.querySelector('.atlas-controls');
  if (ctrl) {
    ctrl.querySelectorAll('button[data-cell]').forEach(btn => {
      btn.addEventListener('click', () => {
        ctrl.querySelectorAll('button').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const view = btn.dataset.cell;
        svg.querySelectorAll('.cell-view').forEach(v => v.style.display = 'none');
        const target = svg.querySelector(`.view-${view}`);
        if (target) target.style.display = '';
        // Reset panel + active state
        svg.classList.remove('has-active');
        svg.querySelectorAll('.organelle').forEach(o => o.classList.remove('active'));
        panel.innerHTML = `
          <div class="atlas-empty">
            <h4>Click any structure</h4>
            <p>Each organelle reveals its function, where it shows up on the DAT, and a link to its deep-dive node.</p>
          </div>
        `;
      });
    });
  }
}

function relocateNodesToSections() {
  // Move misplaced node sections into their proper section blocks
  document.querySelectorAll('[data-node-target]').forEach(slot => {
    const targetId = slot.dataset.nodeTarget;
    const node = document.querySelector(`section.node[data-node="${targetId}"]`);
    if (node) slot.appendChild(node);
  });
}

/* ---- LAB TAB SWITCHING (flagship-scoped) ---- */
function initLabTabs() {
  document.querySelectorAll('.flagship').forEach(flagship => {
    const tabs = flagship.querySelectorAll('.lab-tabs > button');
    const modules = flagship.querySelectorAll(':scope > .lab-module');
    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        tabs.forEach(t => t.classList.remove('active'));
        modules.forEach(m => m.classList.remove('active'));
        tab.classList.add('active');
        const target = flagship.querySelector(`:scope > .lab-module[data-module="${tab.dataset.tab}"]`);
        if (target) target.classList.add('active');
      });
    });
  });
}

/* ---- BIOENERGETICS PATHWAY MAP ---- */
const ENERGY_STEPS = {
  "g-glucose": { stage:"Glycolysis · cytoplasm", name:"Glucose (6C)", desc:"Starting substrate. 6-carbon sugar enters glycolysis. Net per glucose: 2 ATP, 2 NADH, 2 pyruvate.", enz:["—"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "g-hex": { stage:"Glycolysis · step 1", name:"Hexokinase / Glucokinase", desc:"Phosphorylates glucose → G6P, traps it in cell. Costs 1 ATP. <b>Hexokinase</b> = low Km (most tissues). <b>Glucokinase</b> = high Km (liver, only kicks in at high blood glucose).", enz:["Hexokinase","Glucokinase"], y:{atp:-1,nadh:0,fadh2:0,co2:0} },
  "g-pfk": { stage:"Glycolysis · step 3 · RATE-LIMITING", name:"PFK-1", desc:"<b>Phosphofructokinase-1</b>. Committed step, rate-limiting. F6P → F1,6BP, costs 1 ATP. Inhibited by ATP, citrate (high energy). Activated by AMP, ADP, F2,6BP (low energy + insulin signal).", enz:["PFK-1"], y:{atp:-1,nadh:0,fadh2:0,co2:0} },
  "g-split": { stage:"Glycolysis · step 4", name:"Aldolase", desc:"Cleaves F1,6BP into 2× G3P (3-carbon each). Now 2 molecules per glucose proceed.", enz:["Aldolase"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "g-payoff": { stage:"Glycolysis · payoff phase", name:"Payoff (steps 6-10)", desc:"2× G3P → 2× pyruvate. Generates 4 ATP (substrate-level phosphorylation) + 2 NADH. <b>Pyruvate kinase</b> is the final enzyme. Net glycolysis = -2 + 4 ATP = +2 ATP.", enz:["GAPDH","PGK","Enolase","Pyruvate kinase"], y:{atp:4,nadh:2,fadh2:0,co2:0} },
  "g-pyruvate": { stage:"Glycolysis end", name:"Pyruvate (3C) ×2", desc:"2 pyruvate per glucose. Enters mitochondrion via pyruvate translocase. If anaerobic: → lactate (mammals) or ethanol (yeast). If aerobic: → acetyl-CoA via PDH.", enz:["—"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "pdh": { stage:"PDH complex · matrix", name:"Pyruvate dehydrogenase", desc:"<b>PDH</b> oxidatively decarboxylates pyruvate → acetyl-CoA. Per glucose: produces 2 NADH + 2 CO₂. Requires 5 cofactors: TPP, lipoic acid, CoA, FAD, NAD⁺. Inhibited by acetyl-CoA, NADH, ATP (product inhibition).", enz:["PDH complex"], y:{atp:0,nadh:2,fadh2:0,co2:2} },
  "k-citrate": { stage:"Krebs · step 1", name:"Citrate synthase", desc:"Acetyl-CoA + OAA → citrate (6C). Inhibited by ATP, NADH, succinyl-CoA, citrate.", enz:["Citrate synthase"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "k-isocit": { stage:"Krebs · step 3 · RATE-LIMITING", name:"Isocitrate DH", desc:"<b>Isocitrate DH</b> is rate-limiting for Krebs. Isocitrate → α-ketoglutarate. Per turn: -1 CO₂, +1 NADH. Activated by ADP, Ca²⁺. Inhibited by ATP, NADH.", enz:["Isocitrate DH"], y:{atp:0,nadh:1,fadh2:0,co2:1} },
  "k-akg": { stage:"Krebs · step 4", name:"α-Ketoglutarate DH", desc:"α-KG → succinyl-CoA. Mechanistically similar to PDH. Per turn: -1 CO₂, +1 NADH. The 2 CO₂ atoms released in Krebs come from steps 3 + 4.", enz:["α-KG DH"], y:{atp:0,nadh:1,fadh2:0,co2:1} },
  "k-succoa": { stage:"Krebs · step 5", name:"Succinyl-CoA synthetase", desc:"Substrate-level phosphorylation. Succ-CoA → succinate, generates 1 GTP (≈ 1 ATP).", enz:["Succinyl-CoA synthetase"], y:{atp:1,nadh:0,fadh2:0,co2:0} },
  "k-succinate": { stage:"Krebs · step 6 · IS Complex II", name:"Succinate DH", desc:"<b>Succinate DH = Complex II of ETC</b>. The only Krebs enzyme embedded in inner membrane. Succinate → fumarate, +1 FADH₂ (lower energy than NADH because skips Complex I).", enz:["Succinate DH"], y:{atp:0,nadh:0,fadh2:1,co2:0} },
  "k-fumarate": { stage:"Krebs · step 7", name:"Fumarase", desc:"Fumarate → malate. Adds water across the double bond.", enz:["Fumarase"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "k-malate": { stage:"Krebs · step 8", name:"Malate DH", desc:"Malate → OAA, +1 NADH. OAA cycles back to combine with next acetyl-CoA.", enz:["Malate DH"], y:{atp:0,nadh:1,fadh2:0,co2:0} },
  "k-oaa": { stage:"Krebs cycle continues", name:"Oxaloacetate", desc:"Cycle restarts: OAA + acetyl-CoA → citrate. <b>Per glucose, Krebs runs 2×.</b> Total: 6 NADH + 2 FADH₂ + 2 GTP + 4 CO₂.", enz:["—"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "etc-c1": { stage:"ETC · inner mitochondrial membrane", name:"Complex I (NADH dehydrogenase)", desc:"NADH → NAD⁺, electrons enter Q. Pumps <b>4 H⁺</b> from matrix to intermembrane space. <b>Inhibited by rotenone</b> (insecticide).", enz:["NADH-Q reductase"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "etc-c2": { stage:"ETC · entry from FADH₂", name:"Complex II (Succinate DH)", desc:"FADH₂ feeds electrons in. <b>Does NOT pump H⁺</b> — that's why FADH₂ yields less ATP than NADH (1.5 vs 2.5).", enz:["Succinate DH"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "etc-c3": { stage:"ETC · cytochrome bc1", name:"Complex III", desc:"Cytochrome bc1. Q → cytochrome c. Pumps <b>4 H⁺</b>. <b>Inhibited by antimycin A</b>. Q-cycle.", enz:["Cytochrome bc1"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "etc-c4": { stage:"ETC · final electron transfer", name:"Complex IV (Cytochrome c oxidase)", desc:"Final electron transfer to O₂ → H₂O. Pumps <b>2 H⁺</b>. <b>Inhibited by cyanide, CO, azide</b> — these are lethal because they shut down ETC entirely.", enz:["Cytochrome c oxidase"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
  "etc-c5": { stage:"Chemiosmosis · ATP synthase", name:"Complex V (ATP synthase)", desc:"H⁺ flows back through ATP synthase, F₀F₁ rotor synthesizes ATP. ~28 ATP per glucose come from oxidative phosphorylation. <b>Oligomycin</b> inhibits the F₀ proton channel. <b>2,4-DNP</b> uncouples (shuttles H⁺ across membrane → heat, not ATP).", enz:["ATP synthase F₀F₁"], y:{atp:0,nadh:0,fadh2:0,co2:0} },
};

const ENERGY_STATE = { atp:0, nadh:0, fadh2:0, co2:0 };

function updateEnergyCounters() {
  const total = ENERGY_STATE.atp + (ENERGY_STATE.nadh * 2.5) + (ENERGY_STATE.fadh2 * 1.5);
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set("counter-atp", ENERGY_STATE.atp);
  set("counter-nadh", ENERGY_STATE.nadh);
  set("counter-fadh2", ENERGY_STATE.fadh2);
  set("counter-co2", ENERGY_STATE.co2);
  set("counter-total", total.toFixed(1));
}

function initBioenergetics() {
  const svg = document.getElementById("energySvg");
  const info = document.getElementById("energyStepInfo");
  if (!svg || !info) return;

  svg.querySelectorAll(".step").forEach(el => {
    el.addEventListener("click", () => {
      const id = el.dataset.step;
      const d = ENERGY_STEPS[id];
      if (!d) return;
      svg.querySelectorAll(".step").forEach(s => s.classList.remove("active"));
      el.classList.add("active");
      const enzHTML = (d.enz || []).map(e => `<span class="enz">${e}</span>`).join("");
      const y = d.y;
      const yieldText = (y.atp || y.nadh || y.fadh2 || y.co2)
        ? `<div class="yield"><b>Yield:</b> ${y.atp?`${y.atp>0?"+":""}${y.atp} ATP `:""}${y.nadh?`+${y.nadh} NADH `:""}${y.fadh2?`+${y.fadh2} FADH₂ `:""}${y.co2?`+${y.co2} CO₂`:""}</div>`
        : "";
      info.innerHTML = `<div class="stage-lbl">${d.stage}</div><h5>${d.name}</h5><p>${d.desc}</p>${enzHTML?`<div style="margin-top:10px">${enzHTML}</div>`:""}${yieldText}`;
    });
  });

  const reset = document.getElementById("energy-reset");
  if (reset) reset.addEventListener("click", () => {
    ENERGY_STATE.atp = 0; ENERGY_STATE.nadh = 0; ENERGY_STATE.fadh2 = 0; ENERGY_STATE.co2 = 0;
    updateEnergyCounters();
    svg.querySelectorAll(".step").forEach(s => s.classList.remove("active"));
  });

  const fullBtn = document.getElementById("energy-full");
  if (fullBtn) fullBtn.addEventListener("click", () => {
    // Per-glucose totals from full aerobic respiration
    ENERGY_STATE.atp = 4; // 2 glycolysis + 2 GTP from Krebs
    ENERGY_STATE.nadh = 10; // 2 glycolysis + 2 PDH + 6 Krebs
    ENERGY_STATE.fadh2 = 2; // 2 from Krebs
    ENERGY_STATE.co2 = 6; // 2 from PDH + 4 from Krebs
    updateEnergyCounters();
    info.innerHTML = `<div class="stage-lbl">Full aerobic respiration · per glucose</div><h5>Per-glucose totals</h5><p><b>ATP (substrate-level):</b> 4 (2 from glycolysis + 2 GTP from Krebs)<br><b>NADH:</b> 10 (2 glycolysis + 2 PDH + 6 Krebs)<br><b>FADH₂:</b> 2 (Krebs)<br><b>CO₂:</b> 6 (2 PDH + 4 Krebs)</p><div class="yield"><b>Total ATP equiv:</b> 4 + (10 × 2.5) + (2 × 1.5) = <b>32 ATP</b> per glucose. (Older texts say 36-38; refined value accounts for shuttle costs to move cytoplasmic NADH into mitochondria.)</div>`;
  });

  updateEnergyCounters();
}

/* ---- LAB BENCH: GEL ELECTROPHORESIS ---- */
const GEL_LADDER = [{size:5000,y:60},{size:2000,y:90},{size:1000,y:120},{size:500,y:160},{size:250,y:200},{size:100,y:240}];
const GEL_LANES = { 1:GEL_LADDER, 2:[], 3:[], 4:[] };

function gelYFromSize(size) {
  // size 100 = y 240, size 5000 = y 60. Log scale.
  const log = Math.log10(size);
  // log 2 (100) → 240; log 3.7 (5000) → 60. Linear interp.
  const minL = 2, maxL = 3.7;
  const minY = 240, maxY = 60;
  const t = (log - minL) / (maxL - minL);
  return minY + (maxY - minY) * Math.max(0, Math.min(1, t));
}

function renderGel(run) {
  const svg = document.getElementById("gelBands");
  if (!svg) return;
  svg.innerHTML = "";
  const lanes = { 1:65, 2:130, 3:195, 4:260 };
  Object.entries(GEL_LANES).forEach(([lane, frags]) => {
    const x = lanes[lane];
    frags.forEach(f => {
      const targetY = run ? gelYFromSize(f.size) : 35;
      const band = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      band.setAttribute("x", x - 22);
      band.setAttribute("y", targetY - 3);
      band.setAttribute("width", 44);
      band.setAttribute("height", 5);
      band.setAttribute("fill", "#1B3A2D");
      band.setAttribute("opacity", 0.85);
      band.setAttribute("rx", 2);
      svg.appendChild(band);
      if (lane === "1") {
        const lbl = document.createElementNS("http://www.w3.org/2000/svg", "text");
        lbl.setAttribute("x", 30);
        lbl.setAttribute("y", targetY + 2);
        lbl.setAttribute("font-size", 8);
        lbl.setAttribute("fill", "#1B3A2D");
        lbl.setAttribute("font-weight", "700");
        lbl.setAttribute("text-anchor", "end");
        lbl.textContent = f.size + "bp";
        svg.appendChild(lbl);
      }
    });
  });
}

function initGel() {
  renderGel(false);
  const readout = document.getElementById("gelReadout");
  document.querySelectorAll('[data-gel]').forEach(btn => {
    btn.addEventListener("click", () => {
      const a = btn.dataset.gel;
      if (a === "load2-mix") { GEL_LANES[2] = [{size:3000},{size:800},{size:200}]; readout.innerHTML = "Lane 2: <b>3000, 800, 200 bp</b> mix loaded."; renderGel(false); }
      else if (a === "load3-large") { GEL_LANES[3] = [{size:4000}]; readout.innerHTML = "Lane 3: <b>4000 bp</b> single fragment loaded."; renderGel(false); }
      else if (a === "load4-small") { GEL_LANES[4] = [{size:150}]; readout.innerHTML = "Lane 4: <b>150 bp</b> small fragment loaded."; renderGel(false); }
      else if (a === "run") { renderGel(true); readout.innerHTML = "<b>Gel run.</b> Smaller fragments traveled farther toward the +. Compare lanes against the ladder to estimate sizes."; }
      else if (a === "reset") { GEL_LANES[2] = []; GEL_LANES[3] = []; GEL_LANES[4] = []; renderGel(false); readout.innerHTML = "Gel reset. Load samples → Run gel."; }
    });
  });
}

/* ---- LAB BENCH: PCR CYCLE VISUALIZER ---- */
const PCR_STATE = { cycle:0, copies:1 };
function renderPCR() {
  const tubes = document.getElementById("pcrTubes");
  if (!tubes) return;
  tubes.innerHTML = "";
  // Show 8 tubes with heights proportional to log copies
  const showCount = Math.min(8, Math.max(1, Math.ceil(PCR_STATE.copies / Math.max(1, PCR_STATE.copies / 8))));
  const log = Math.log2(Math.max(1, PCR_STATE.copies));
  const baseHeight = 30;
  const heightPerLog = 18;
  const h = Math.min(220, baseHeight + log * heightPerLog);
  for (let i = 0; i < 8; i++) {
    const tube = document.createElement("div");
    tube.className = "pcr-tube";
    tube.style.height = h + "px";
    const cap = document.createElement("div");
    cap.className = "pcr-cap";
    tube.appendChild(cap);
    tubes.appendChild(tube);
  }
  document.getElementById("pcrReadout").innerHTML = `Cycle: <b>${PCR_STATE.cycle}</b> &middot; Copies: <b>${PCR_STATE.copies.toLocaleString()}</b>`;
}

function pcrAnimate(cycles, done) {
  let c = 0;
  const phases = [
    { temp: "95°C · DENATURE", t: 200 },
    { temp: "55°C · ANNEAL", t: 200 },
    { temp: "72°C · EXTEND", t: 200 },
  ];
  const readout = document.getElementById("pcrThermoReadout");
  function runCycle() {
    if (c >= cycles) { readout.textContent = `Cycle ${PCR_STATE.cycle} · Idle`; if (done) done(); return; }
    let p = 0;
    function nextPhase() {
      if (p >= phases.length) {
        PCR_STATE.cycle++;
        PCR_STATE.copies = Math.min(1e12, PCR_STATE.copies * 2);
        renderPCR();
        c++;
        setTimeout(runCycle, 50);
        return;
      }
      readout.textContent = phases[p].temp;
      setTimeout(() => { p++; nextPhase(); }, phases[p].t);
    }
    nextPhase();
  }
  runCycle();
}

function initPCR() {
  renderPCR();
  document.querySelectorAll('[data-pcr]').forEach(btn => {
    btn.addEventListener("click", () => {
      const a = btn.dataset.pcr;
      if (a === "cycle") pcrAnimate(1);
      else if (a === "five") pcrAnimate(5);
      else if (a === "thirty") pcrAnimate(30);
      else if (a === "reset") { PCR_STATE.cycle = 0; PCR_STATE.copies = 1; renderPCR(); document.getElementById("pcrThermoReadout").textContent = "Cycle 0 · Idle"; }
    });
  });
}

/* ---- LAB BENCH: MICROSCOPY LADDER ---- */
const MAG_DATA = {
  naked: { name:"Naked eye", body:"~100 μm resolution. You can see most cells barely as specks. <b>Hair</b> is ~80 μm (visible), <b>RBC</b> is ~7 μm (not visible). Useful for tissues, organisms." },
  light: { name:"Light microscope", body:"<b>~200 nm resolution</b> (Abbe limit, set by visible light wavelength λ ≈ 400–700 nm). <b>Magnification = ocular × objective</b> (e.g., 10× × 100× = 1000×). Sees cells, large organelles (nucleus, mito), fixed/stained samples. Hematoxylin + eosin standard stain." },
  fluor: { name:"Fluorescence microscope", body:"Same ~200 nm resolution as light. Uses fluorophore-tagged antibodies/probes (immunofluorescence, FISH for DNA/RNA, GFP for live proteins). Excitation light → emission at longer wavelength. Reveals specific molecules." },
  confocal: { name:"Confocal microscope", body:"Pinhole rejects out-of-focus light → optical sectioning. ~180 nm resolution. Builds 3D stacks of thin sections. Used for thick tissues + live cells." },
  sem: { name:"Scanning electron microscope (SEM)", body:"Electrons scan the surface; detectors capture secondary electrons. <b>~1 nm resolution</b>. Surface topology, 3D-look. Sample sputtered with conductive metal (gold). Cannot see internal structure." },
  tem: { name:"Transmission electron microscope (TEM)", body:"Electrons pass THROUGH ultra-thin sections. <b>~0.05 nm resolution</b>. Sees internal ultrastructure: ribosomes, cristae, cisternae. Sample fixed + heavy-metal stained (osmium, uranyl acetate). Black-and-white." },
};

function initMicroscopy() {
  const rungs = document.querySelectorAll(".mag-rung");
  const out = document.getElementById("magReadout");
  rungs.forEach(r => {
    r.addEventListener("click", () => {
      rungs.forEach(x => x.classList.remove("active"));
      r.classList.add("active");
      const d = MAG_DATA[r.dataset.mag];
      if (d && out) out.innerHTML = `<b>${d.name}</b>: ${d.body}`;
    });
  });
}

/* ---- ENZYME KINETICS PLOTTER ---- */
const KIN_STATE = { mode:"none", I:0, Km:10 };

function buildMMPath(Km, Vmax, originX, originY, axisLen, maxS) {
  // Map x: [0, maxS] → [originX, originX + axisLen]
  // Map y: [0, Vmax_global] → [originY, originY - axisLenY]
  const axisLenY = 320; // 400 - 80
  const Vmax_global = 1.0; // reference
  const w = 500, h = 320;
  let d = `M ${originX} ${originY}`;
  for (let i = 0; i <= 80; i++) {
    const s = (i / 80) * maxS;
    const v = (Vmax * s) / (Km + s);
    const x = originX + (s / maxS) * w;
    const y = originY - (v / Vmax_global) * h;
    d += ` L ${x.toFixed(2)} ${y.toFixed(2)}`;
  }
  return d;
}

function updateKinetics() {
  const baseSvg = document.getElementById("kinCurveBase");
  if (!baseSvg) return;
  const inhibSvg = document.getElementById("kinCurveInhib");
  const kmLine = document.getElementById("kinKmLine");
  const kmLabel = document.getElementById("kinKmLabel");
  const out = document.getElementById("kinReadout");
  const Km0 = KIN_STATE.Km;
  const I = KIN_STATE.I / 100;
  const maxS = 80; // arbitrary substrate concentration max
  let Km_eff = Km0, Vmax_eff = 1.0;
  let blurb = "";

  if (KIN_STATE.mode === "comp") {
    Km_eff = Km0 * (1 + 3*I); Vmax_eff = 1.0;
    blurb = `<b>Competitive</b> — inhibitor binds active site, substrate competes. <span class="arrow">↑</span> K<sub>m</sub> = ${Km_eff.toFixed(1)} (was ${Km0}). V<sub>max</sub> unchanged. Lineweaver-Burk: same y-intercept, different x-intercept.`;
  } else if (KIN_STATE.mode === "noncomp") {
    Km_eff = Km0; Vmax_eff = 1 - 0.7*I;
    blurb = `<b>Noncompetitive</b> — inhibitor binds allosteric site, lowers effective enzyme. <span class="arrow">↓</span> V<sub>max</sub> = ${Vmax_eff.toFixed(2)}. K<sub>m</sub> unchanged at ${Km0}. Lineweaver-Burk: different y-intercept, same x-intercept.`;
  } else if (KIN_STATE.mode === "uncomp") {
    Km_eff = Km0 * (1 - 0.5*I); Vmax_eff = 1 - 0.5*I;
    blurb = `<b>Uncompetitive</b> — inhibitor binds only the ES complex. <span class="arrow">↓</span> Both K<sub>m</sub> (${Km_eff.toFixed(1)}) AND V<sub>max</sub> (${Vmax_eff.toFixed(2)}) decrease proportionally. Lineweaver-Burk: parallel lines.`;
  } else {
    blurb = `<b>None</b> — baseline kinetics. K<sub>m</sub> = ${Km0}, V<sub>max</sub> = 1.0. K<sub>m</sub> is the [S] at half V<sub>max</sub>. Low K<sub>m</sub> = high affinity.`;
  }

  baseSvg.setAttribute("d", buildMMPath(Km0, 1.0, 60, 400, 500, maxS));
  inhibSvg.setAttribute("d", buildMMPath(Km_eff, Vmax_eff, 60, 400, 500, maxS));
  // Km marker — find x position where curve hits Vmax/2
  const xKm = 60 + (Km_eff / maxS) * 500;
  const yHalf = 400 - (Vmax_eff / 2 / 1.0) * 320;
  kmLine.setAttribute("x1", xKm); kmLine.setAttribute("x2", xKm);
  kmLine.setAttribute("y1", yHalf); kmLine.setAttribute("y2", 400);
  kmLabel.setAttribute("x", xKm);
  out.innerHTML = blurb;
}

function initKinetics() {
  document.querySelectorAll('#kinModes button').forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll('#kinModes button').forEach(b => b.classList.remove("on"));
      btn.classList.add("on");
      KIN_STATE.mode = btn.dataset.mode;
      updateKinetics();
    });
  });
  const iSlider = document.getElementById("kinISlider");
  const kmSlider = document.getElementById("kinKmSlider");
  if (iSlider) iSlider.addEventListener("input", e => { KIN_STATE.I = +e.target.value; document.getElementById("kinIVal").textContent = KIN_STATE.I + "%"; updateKinetics(); });
  if (kmSlider) kmSlider.addEventListener("input", e => { KIN_STATE.Km = +e.target.value; document.getElementById("kinKmVal").textContent = KIN_STATE.Km; updateKinetics(); });
  updateKinetics();
}

/* ---- CELL CYCLE WHEEL ---- */
const CYCLE_DATA = {
  g1: { name:"G1 phase", lbl:"Gap 1 · growth", body:"Cell grows in size, synthesizes RNA and proteins, and prepares for DNA replication. <b>Cyclin D + CDK4/6</b> drive G1 progression. <b>Restriction point</b> at end of G1 — past this point, cell is committed to division (or exits to G0)." },
  s: { name:"S phase", lbl:"Synthesis · DNA doubles", body:"DNA replication. Each chromosome → 2 sister chromatids joined at centromere. <b>Cyclin E + CDK2</b> initiates; <b>Cyclin A + CDK2</b> drives DNA synthesis. Centrosome also duplicates here." },
  g2: { name:"G2 phase", lbl:"Gap 2 · prep for mitosis", body:"Cell synthesizes proteins needed for mitosis (e.g., tubulin for spindle). Final growth + DNA repair check. <b>Cyclin B + CDK1 (MPF)</b> rises, drives entry into M." },
  m: { name:"M phase", lbl:"Mitosis + cytokinesis", body:"<b>PMAT</b>: Prophase, Metaphase, Anaphase, Telophase. Then cytokinesis (cleavage furrow in animals, cell plate in plants). Cyclin B drops sharply at anaphase (cohesin cleaved by separase). Net: 1 cell → 2 identical daughters." },
};

const CHECKPOINT_DATA = {
  g1s: { name:"G1/S Restriction Checkpoint", lbl:"END OF G1", body:"<b>Most important checkpoint.</b> Checks: cell size adequate? nutrients available? DNA undamaged? growth signals present? <b>p53</b> halts progression if DNA damage. <b>Rb</b> sequesters E2F transcription factor; phosphorylated by Cyclin D-CDK4 → E2F released → S-phase genes on. Past this point, cell is committed; otherwise enters G0." },
  g2m: { name:"G2/M Checkpoint", lbl:"END OF G2", body:"Verifies DNA fully replicated and undamaged before mitosis. <b>p53</b> can halt here too. Activated by ATM/ATR kinases sensing DNA damage. Cyclin B-CDK1 (MPF) must reach threshold to proceed." },
  spindle: { name:"Spindle (Metaphase) Checkpoint", lbl:"DURING M PHASE", body:"Verifies all chromosomes are properly attached to spindle microtubules at the metaphase plate. <b>MAD/BUB</b> proteins block anaphase until every kinetochore is bi-oriented. If a chromosome isn't attached → APC/C inhibited → no separase activation → no anaphase. Failure here = aneuploidy (Down syndrome from nondisjunction)." },
};

/* ---- PUNNETT SOLVER ---- */
const PUNNETT_STATE = { mode: "mono" };

function gametesFromGenotype(geno, mode) {
  // Strip whitespace, accept superscripts written as ^X
  const g = geno.replace(/\s+/g, "").replace(/\^/g, "");
  if (mode === "xlinked") {
    // Expects X^A, X^a, Y patterns. We'll parse simple: X[A-Za-z] or Y
    const re = /X[A-Za-z]|Y/g;
    const alleles = g.match(re) || [];
    return Array.from(new Set(alleles));
  }
  if (mode === "abo") {
    // Map "A","B","O" to alleles. Input like "AB","AO","BO","AA","BB","OO"
    const map = {A:"Iᴬ", B:"Iᴮ", O:"i"};
    const alleles = g.split("").map(c => map[c.toUpperCase()] || c);
    return Array.from(new Set(alleles));
  }
  if (mode === "dihybrid") {
    if (g.length < 4) return [];
    // Two genes, 2 alleles each. Generate 2^2 = 4 combos (both pairs).
    const a = [g[0], g[1]];
    const b = [g[2], g[3]];
    const set = new Set();
    a.forEach(x => b.forEach(y => set.add(x + y)));
    return Array.from(set);
  }
  // mono / incomp / codom
  if (g.length < 2) return [];
  return Array.from(new Set([g[0], g[1]]));
}

function combineGametes(g1, g2, mode) {
  // For dihybrid: g1 and g2 are 2-letter strings (one for each gene)
  if (mode === "dihybrid") {
    // g1 = "AB", g2 = "ab" → genotype "AaBb" (sort within each gene by uppercase first)
    const sortPair = (a,b) => {
      if (a.toLowerCase() === b.toLowerCase()) return [a,b].sort().reverse(); // capital first
      return [a,b];
    };
    const gene1 = sortPair(g1[0], g2[0]).join("");
    const gene2 = sortPair(g1[1], g2[1]).join("");
    return gene1 + gene2;
  }
  if (mode === "xlinked") {
    // Each gamete is X^A, X^a, or Y. Combine sorted: X first, then Y.
    if (g1 === "Y") return g2 + "Y";
    if (g2 === "Y") return g1 + "Y";
    return [g1, g2].sort().join("");
  }
  if (mode === "abo") {
    return [g1, g2].sort().join("");
  }
  // simple alleles
  return [g1, g2].sort((a,b) => {
    if (a.toLowerCase() === b.toLowerCase()) return a > b ? 1 : -1; // capital first
    return a > b ? 1 : -1;
  }).join("");
}

function phenotypeOf(geno, mode) {
  if (mode === "incomp") {
    // For "Aa": pink (intermediate). "AA": red. "aa": white.
    if (geno.length === 2) {
      if (geno[0] === geno[1]) {
        return geno[0] === geno[0].toUpperCase() ? "red" : "white";
      }
      return "pink";
    }
  }
  if (mode === "codom") {
    if (geno.length === 2) {
      if (geno[0] === geno[1]) {
        return geno[0] === geno[0].toUpperCase() ? "homo dom" : "homo rec";
      }
      return "BOTH expressed";
    }
  }
  if (mode === "abo") {
    const A = (geno.match(/Iᴬ/g) || []).length;
    const B = (geno.match(/Iᴮ/g) || []).length;
    const i = (geno.match(/i/g) || []).length;
    if (A && B) return "Type AB";
    if (A) return "Type A";
    if (B) return "Type B";
    return "Type O";
  }
  if (mode === "xlinked") {
    // Recessive trait, denoted lowercase superscript
    if (geno.includes("Y")) {
      const x = geno.replace("Y","");
      return x[1] && x[1] === x[1].toLowerCase() ? "AFFECTED male" : "unaffected male";
    }
    // Two X's
    const a1 = geno[1], a2 = geno[3];
    if (a1 === a1.toLowerCase() && a2 === a2.toLowerCase()) return "AFFECTED female";
    if (a1 === a1.toLowerCase() || a2 === a2.toLowerCase()) return "carrier female";
    return "unaffected female";
  }
  if (mode === "dihybrid") {
    // 4-letter: AaBb. Phenotype: A_B_, A_bb, aaB_, aabb
    const A = geno[0] === geno[0].toUpperCase() || (geno[1] && geno[1] === geno[1].toUpperCase());
    const B = geno[2] === geno[2].toUpperCase() || (geno[3] && geno[3] === geno[3].toUpperCase());
    return (A ? "A·" : "a·") + (B ? "B" : "b");
  }
  // monohybrid simple
  if (geno.length === 2) {
    const dom = geno[0] === geno[0].toUpperCase() || geno[1] === geno[1].toUpperCase();
    return dom ? "dominant" : "recessive";
  }
  return "?";
}

function classifyPunnettCell(pheno, mode) {
  if (mode === "incomp" || mode === "codom") return "codom";
  if (pheno && (pheno.includes("AFFECTED") || pheno.includes("recessive") || pheno.includes("aabb") || pheno === "Type O" || pheno === "homo rec")) return "rec-pheno";
  return "dom-pheno";
}

function renderPunnett() {
  const wrap = document.getElementById("punnettWrap");
  const side = document.getElementById("punnettSide");
  const mode = PUNNETT_STATE.mode;
  const p1 = document.getElementById("p1Geno").value.trim();
  const p2 = document.getElementById("p2Geno").value.trim();
  const g1 = gametesFromGenotype(p1, mode);
  const g2 = gametesFromGenotype(p2, mode);
  if (!g1.length || !g2.length) {
    wrap.innerHTML = '<p style="color:var(--ink-mute);font-size:13px;padding:24px">Enter parent genotypes (e.g., <b>Aa</b> or <b>AaBb</b>) and click Compute.</p>';
    return;
  }
  // Build table
  let html = "<table class='punnett-table'><tr><th class='corner'></th>";
  g1.forEach(a => html += `<th class='gamete-p1'>${a}</th>`);
  html += "</tr>";

  const tally = {};
  g2.forEach(b => {
    html += `<tr><th class='gamete-p2'>${b}</th>`;
    g1.forEach(a => {
      const offspring = combineGametes(a, b, mode);
      const pheno = phenotypeOf(offspring, mode);
      const cls = classifyPunnettCell(pheno, mode);
      tally[offspring] = (tally[offspring] || 0) + 1;
      html += `<td class='${cls}'>${offspring}<span class='pheno'>${pheno}</span></td>`;
    });
    html += "</tr>";
  });
  html += "</table>";
  wrap.innerHTML = html;

  // Compute ratios for side panel
  const totalCells = g1.length * g2.length;
  const phenoTally = {};
  Object.entries(tally).forEach(([geno, n]) => {
    const pheno = phenotypeOf(geno, mode);
    phenoTally[pheno] = (phenoTally[pheno] || 0) + n;
  });
  const genoStr = Object.entries(tally).map(([g,n]) => `<div class="gen-ratio-row"><span class="lbl">${g}</span><span class="val">${n}/${totalCells}</span></div>`).join("");
  const phenoStr = Object.entries(phenoTally).map(([p,n]) => `<div class="gen-ratio-row"><span class="lbl">${p}</span><span class="val">${n}/${totalCells}</span></div>`).join("");

  side.innerHTML = `
    <div class="energy-step-info">
      <div class="stage-lbl">${{mono:"Monohybrid",dihybrid:"Dihybrid",incomp:"Incomplete Dom",codom:"Codominance",abo:"ABO Blood",xlinked:"Sex-linked"}[mode]}</div>
      <h5>${p1} × ${p2}</h5>
      <div class="gen-readout"><b>Genotype ratio</b>${genoStr}</div>
      <div class="gen-readout" style="margin-top:10px"><b>Phenotype ratio</b>${phenoStr}</div>
    </div>
  `;
}

function initPunnett() {
  if (!document.getElementById('punnettCompute')) return;
  document.querySelectorAll('#punnettModes [data-pmode]').forEach(p => {
    p.addEventListener("click", () => {
      document.querySelectorAll('#punnettModes [data-pmode]').forEach(x => x.classList.remove("on"));
      p.classList.add("on");
      PUNNETT_STATE.mode = p.dataset.pmode;
      // Suggest defaults
      const defaults = { mono:["Aa","Aa"], dihybrid:["AaBb","AaBb"], incomp:["Rr","Rr"], codom:["Rr","Rr"], abo:["AB","Ai"], xlinked:["XHXh","XHY"] };
      const d = defaults[PUNNETT_STATE.mode];
      if (d) {
        document.getElementById("p1Geno").value = d[0];
        document.getElementById("p2Geno").value = d[1];
      }
      renderPunnett();
    });
  });
  document.getElementById("punnettCompute").addEventListener("click", renderPunnett);
  document.getElementById("punnettPreset").addEventListener("click", () => {
    document.getElementById("p1Geno").value = "Aa";
    document.getElementById("p2Geno").value = "Aa";
    PUNNETT_STATE.mode = "mono";
    document.querySelectorAll('#punnettModes [data-pmode]').forEach(x => x.classList.toggle("on", x.dataset.pmode === "mono"));
    renderPunnett();
  });
  document.getElementById("punnettPreset2").addEventListener("click", () => {
    document.getElementById("p1Geno").value = "AaBb";
    document.getElementById("p2Geno").value = "AaBb";
    PUNNETT_STATE.mode = "dihybrid";
    document.querySelectorAll('#punnettModes [data-pmode]').forEach(x => x.classList.toggle("on", x.dataset.pmode === "dihybrid"));
    renderPunnett();
  });
  renderPunnett();
}

