const WEB_ORGS = [
  // Producers (level 0)
  { id:'grass',     name:'Grass',         emoji:'🌿', level:0, role:'autotroph; photosynthesizes' },
  { id:'phytoplankton', name:'Phytoplankton', emoji:'🟢', level:0, role:'aquatic primary producer' },
  { id:'tree',      name:'Tree',          emoji:'🌳', level:0, role:'autotroph; carbon fixation' },
  { id:'algae',     name:'Algae',         emoji:'🟢', level:0, role:'aquatic autotroph' },
  // 1° consumers (herbivores)
  { id:'rabbit',    name:'Rabbit',        emoji:'🐰', level:1, role:'herbivore — eats grass' },
  { id:'deer',      name:'Deer',          emoji:'🦌', level:1, role:'herbivore — eats trees, grass' },
  { id:'cow',       name:'Cow',           emoji:'🐄', level:1, role:'herbivore — ruminant' },
  { id:'caterpillar', name:'Caterpillar', emoji:'🐛', level:1, role:'herbivore — eats leaves' },
  { id:'zooplankton', name:'Zooplankton', emoji:'🦠', level:1, role:'eats phytoplankton' },
  // 2° consumers (carnivores eating 1°)
  { id:'fox',       name:'Fox',           emoji:'🦊', level:2, role:'carnivore — eats rabbits, mice' },
  { id:'snake',     name:'Snake',         emoji:'🐍', level:2, role:'carnivore — eats rodents, frogs' },
  { id:'frog',      name:'Frog',          emoji:'🐸', level:2, role:'eats insects (caterpillars, flies)' },
  { id:'fish',      name:'Small fish',    emoji:'🐟', level:2, role:'eats zooplankton, smaller fish' },
  // 3° consumers (apex/top carnivores)
  { id:'eagle',     name:'Eagle',         emoji:'🦅', level:3, role:'apex predator — eats foxes, snakes, fish' },
  { id:'shark',     name:'Shark',         emoji:'🦈', level:3, role:'apex marine predator' },
  { id:'lion',      name:'Lion',          emoji:'🦁', level:3, role:'apex savanna predator' },
];

const WEB_STATE = { placed:{}, score:0, attempts:0 };

function renderWebPool() {
  const list = document.getElementById('webOrgList');
  if (!list) return;
  list.innerHTML = '';
  WEB_ORGS.forEach(o => {
    if (WEB_STATE.placed[o.id]) return;
    const div = document.createElement('div');
    div.className = 'web-org';
    div.dataset.org = o.id;
    div.innerHTML = `<span class="web-emoji">${o.emoji}</span><span class="web-name">${o.name}</span>`;
    div.addEventListener('pointerdown', startWebDrag);
    list.appendChild(div);
  });
}

let _webDrag = null;
function startWebDrag(e) {
  const orgId = e.currentTarget.dataset.org;
  const org = WEB_ORGS.find(o => o.id === orgId);
  if (!org) return;
  e.preventDefault();
  const ghost = document.createElement('div');
  ghost.className = 'builder-org-ghost';
  ghost.textContent = `${org.emoji} ${org.name}`;
  document.body.appendChild(ghost);
  ghost.style.left = e.clientX + 'px';
  ghost.style.top = e.clientY + 'px';
  _webDrag = { org, ghost };
  document.addEventListener('pointermove', onWebDragMove);
  document.addEventListener('pointerup', onWebDragEnd, { once:true });
}
function onWebDragMove(e) {
  if (!_webDrag) return;
  _webDrag.ghost.style.left = e.clientX + 'px';
  _webDrag.ghost.style.top = e.clientY + 'px';
  document.querySelectorAll('.lvl-drop').forEach(d => d.classList.remove('dragover'));
  const el = document.elementFromPoint(e.clientX, e.clientY);
  if (el) {
    const drop = el.closest('.lvl-drop');
    if (drop) drop.classList.add('dragover');
  }
}
function onWebDragEnd(e) {
  document.removeEventListener('pointermove', onWebDragMove);
  if (!_webDrag) return;
  const { org, ghost } = _webDrag;
  ghost.remove();
  document.querySelectorAll('.lvl-drop').forEach(d => d.classList.remove('dragover'));
  const el = document.elementFromPoint(e.clientX, e.clientY);
  const dropEl = el && el.closest('.lvl-drop');
  _webDrag = null;
  if (!dropEl) return;
  const targetLevel = parseInt(dropEl.dataset.drop);
  evaluateWebPlacement(org, targetLevel, dropEl);
}
function evaluateWebPlacement(org, targetLevel, dropEl) {
  WEB_STATE.attempts++;
  const fb = document.getElementById('webFb');
  if (org.level === targetLevel) {
    WEB_STATE.score++;
    WEB_STATE.placed[org.id] = targetLevel;
    const tag = document.createElement('div');
    tag.className = 'web-placed';
    tag.innerHTML = `<span class="web-emoji">${org.emoji}</span><span>${org.name}</span>`;
    dropEl.appendChild(tag);
    fb.className = 'web-feedback correct';
    fb.innerHTML = `<b>✓ ${org.name} → ${['Producer','1° consumer','2° consumer','3° consumer'][targetLevel]}.</b> ${org.role}`;
    renderWebPool();
    updateWebEnergies();
  } else {
    fb.className = 'web-feedback wrong';
    fb.innerHTML = `<b>✗ Not quite.</b> ${org.name} is ${['a producer','a 1° consumer (herbivore)','a 2° consumer','a 3° consumer (apex)'][org.level]}, not ${['producer','1° consumer','2° consumer','3° consumer'][targetLevel]}. ${org.role}`;
    addAceCard({
      q: `What trophic level is the <b>${org.name}</b>?`,
      quickHit: `<b>${['Producer','1° consumer','2° consumer','3° consumer'][org.level]}</b>`,
      explanation: `${org.name} is ${org.role}.`,
      origin: 'Food web builder', subject: 'evolution', nodeId: 'eco',
    });
  }
}
function updateWebEnergies() {
  const E0 = parseFloat(document.getElementById('webProducerEnergy')?.value) || 10000;
  const e0 = E0;
  const e1 = E0 * 0.10;
  const e2 = E0 * 0.01;
  const e3 = E0 * 0.001;
  const fmt = v => v.toLocaleString(undefined, {maximumFractionDigits:1}) + ' kcal';
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set('lvl0Energy', fmt(e0));
  set('lvl1Energy', fmt(e1));
  set('lvl2Energy', fmt(e2));
  set('lvl3Energy', fmt(e3));
}
function resetWeb() {
  WEB_STATE.placed = {}; WEB_STATE.score = 0; WEB_STATE.attempts = 0;
  document.querySelectorAll('.lvl-drop').forEach(d => d.innerHTML = '');
  renderWebPool();
  updateWebEnergies();
  const fb = document.getElementById('webFb');
  if (fb) { fb.className = 'web-feedback'; fb.innerHTML = '<b>Reset.</b> Drag organisms onto trophic levels.'; }
}
function initFoodWeb() {
  if (!document.getElementById('webOrgList')) return;
  renderWebPool();
  updateWebEnergies();
  document.getElementById('webProducerEnergy')?.addEventListener('input', updateWebEnergies);
  document.getElementById('webReset')?.addEventListener('click', resetWeb);
}

/* ---- ALLELE FREQ SIMULATION ---- */
const ALLELE_STATE = { drift: false };
function simulateAllele(p0, s, gens, drift) {
  const traj = [p0];
  let p = p0;
  for (let i = 1; i <= gens; i++) {
    const q = 1 - p;
    // Selection effect: simple weighted update assuming additive fitness
    // After selection: new p = p(1+s) / (p(1+s) + q)
    const num = p * (1 + s);
    const den = num + q;
    p = num / den;
    if (drift) {
      // Add gaussian noise scaled by 1/sqrt(N), assume N=200
      const noise = (Math.random() - 0.5) * 0.06;
      p = Math.max(0, Math.min(1, p + noise));
    }
    traj.push(p);
  }
  return traj;
}

function renderAlleleCurve() {
  const sel = +document.getElementById("alSel").value / 100;
  const p0 = +document.getElementById("alP").value / 100;
  const gens = +document.getElementById("alGen").value;
  const traj = simulateAllele(p0, sel, gens, ALLELE_STATE.drift);

  document.getElementById("alSelVal").textContent = (sel >= 0 ? "+" : "") + sel.toFixed(2);
  document.getElementById("alPVal").textContent = p0.toFixed(2);
  document.getElementById("alGenVal").textContent = gens;

  const w = 500, h = 280;
  const xLeft = 60, yBot = 320;
  let d = "";
  traj.forEach((v, i) => {
    const x = xLeft + (i / gens) * w;
    const y = yBot - v * h;
    d += (i === 0 ? "M " : " L ") + x.toFixed(2) + " " + y.toFixed(2);
  });
  const path = document.getElementById("alleleCurve");
  if (path) path.setAttribute("d", d);
}

function initAlleleSim() {
  ["alSel","alP","alGen"].forEach(id => {
    document.getElementById(id).addEventListener("input", renderAlleleCurve);
  });
  document.getElementById("alRun").addEventListener("click", renderAlleleCurve);
  document.getElementById("alDriftToggle").addEventListener("click", e => {
    ALLELE_STATE.drift = !ALLELE_STATE.drift;
    e.target.classList.toggle("on", ALLELE_STATE.drift);
    renderAlleleCurve();
  });
  document.getElementById("alPresetSweep").addEventListener("click", () => {
    document.getElementById("alSel").value = 30;
    document.getElementById("alP").value = 5;
    document.getElementById("alGen").value = 100;
    renderAlleleCurve();
  });
  document.getElementById("alPresetBalance").addEventListener("click", () => {
    document.getElementById("alSel").value = 0;
    document.getElementById("alP").value = 50;
    document.getElementById("alGen").value = 100;
    ALLELE_STATE.drift = false;
    document.getElementById("alDriftToggle").classList.remove("on");
    renderAlleleCurve();
  });
  renderAlleleCurve();
}

/* ---- SELECTION MODES ---- */
const SEL_DATA = {
  directional: { name:"Directional Selection", body:"<b>One extreme is favored.</b> The mean of the trait shifts over generations. Reduces variation only at the disfavored end. <b>Examples:</b> antibiotic resistance in bacteria, peppered moth darkening during industrial pollution, neck length in giraffes." },
  stabilizing: { name:"Stabilizing Selection", body:"<b>Intermediate phenotypes favored.</b> Both extremes are selected against. <b>Reduces variance, mean unchanged.</b> <b>Examples:</b> human birth weight (~7 lbs optimal), bird clutch size, blood clotting time." },
  disruptive: { name:"Disruptive (Diversifying) Selection", body:"<b>Both extremes favored, intermediates selected against.</b> Can lead to bimodal distribution + sympatric speciation. <b>Examples:</b> African seedcrackers (large vs small beaks), Lake Victoria cichlids." },
  balancing: { name:"Balancing Selection", body:"<b>Maintains polymorphism in a population.</b> Can be heterozygote advantage (sickle cell HbAS resistant to malaria, CF heterozygotes possibly resistant to typhoid/cholera) or frequency-dependent selection (left- vs right-mouth scale-eating cichlids). Sexual selection also a flavor." },
};

function initSelectionModes() {
  const detail = document.getElementById("selDetail");
  document.querySelectorAll('#selSvg [data-sel]').forEach(g => {
    g.addEventListener("click", () => {
      const d = SEL_DATA[g.dataset.sel];
      if (d && detail) detail.innerHTML = `<h5 style="font-family:'Playfair Display',serif;font-size:18px;margin:0 0 6px;font-weight:700">${d.name}</h5><p style="margin:0;font-size:13px;line-height:1.6">${d.body}</p>`;
    });
  });
}

/* ---- SPECIATION MODE CLICK ---- */
const SPEC_DATA = {
  allo: { name:"Allopatric Speciation", body:"<b>Geographic barrier separates populations.</b> Each population accumulates different mutations + faces different selection. Over time → reproductively incompatible. Most common mode. <b>Examples:</b> Grand Canyon squirrels (Kaibab on north rim, Abert on south), Galápagos finches (Darwin), Isthmus of Panama splitting Atlantic + Pacific lineages." },
  sym: { name:"Sympatric Speciation", body:"<b>New species arise WITHOUT geographic separation.</b> Mechanisms: <b>polyploidy</b> (instant speciation, common in plants — autopolyploidy = same species, allopolyploidy = hybrid + chromosome doubling), habitat differentiation (apple maggot fly Rhagoletis: hawthorn vs apple host shift), sexual selection (Lake Victoria cichlid colors)." },
  peri: { name:"Peripatric Speciation", body:"<b>Small peripheral population</b> colonizes a new habitat. <b>Drift-heavy</b> due to small founder size. Special case of allopatric. Faster than ordinary allopatric. <b>Examples:</b> Hawaiian Drosophila (>800 species from few founders), island endemics on isolated archipelagos." },
  para: { name:"Parapatric Speciation", body:"<b>Adjacent populations</b> with a hybrid zone — gene flow continues but a strong environmental gradient drives divergence. <b>Examples:</b> grass tolerance to mine soil at boundaries (Anthoxanthum), some snail color clines." },
};

function initSpeciation() {
  const side = document.getElementById("specSide");
  document.querySelectorAll('[data-spec]').forEach(c => {
    c.addEventListener("click", () => {
      document.querySelectorAll('[data-spec]').forEach(x => x.classList.remove("active"));
      c.classList.add("active");
      const d = SPEC_DATA[c.dataset.spec];
      if (d && side) side.innerHTML = `<div class="energy-step-info"><div class="stage-lbl">Speciation</div><h5>${d.name}</h5><p>${d.body}</p></div>`;
    });
  });
}

/* ---- CELL CYCLE WHEEL ANIMATION ---- */
const CYCLE_ANIM = { playing:false, t:0, animId:null, lastFrame:0 };
const CYCLE_PHASES = [
  { id:'g1', start:0,    end:0.40, name:'G1 phase · growth' },
  { id:'s',  start:0.40, end:0.65, name:'S phase · DNA synthesis' },
  { id:'g2', start:0.65, end:0.85, name:'G2 phase · prep mitosis' },
  { id:'m',  start:0.85, end:1.0,  name:'M phase · mitosis + cytokinesis' },
];
function phaseAtT(t) {
  return CYCLE_PHASES.find(p => t >= p.start && t < p.end) || CYCLE_PHASES[0];
}
function cycleTick(now) {
  if (!CYCLE_ANIM.playing) return;
  if (!CYCLE_ANIM.lastFrame) CYCLE_ANIM.lastFrame = now;
  const dt = (now - CYCLE_ANIM.lastFrame) / 1000;
  CYCLE_ANIM.lastFrame = now;
  // Full cycle in 8 seconds (slow enough to read each phase)
  CYCLE_ANIM.t = (CYCLE_ANIM.t + dt / 8) % 1;
  const angle = CYCLE_ANIM.t * 2 * Math.PI - Math.PI / 2;  // -90° offset so 0 = top
  const cx = 220, cy = 220, r = 160;
  const x = cx + r * Math.cos(angle);
  const y = cy + r * Math.sin(angle);
  const line = document.getElementById('cycleArmLine');
  const head = document.getElementById('cycleArmHead');
  if (line) { line.setAttribute('x2', x); line.setAttribute('y2', y); }
  if (head) { head.setAttribute('cx', x); head.setAttribute('cy', y); }
  const phaseLbl = document.getElementById('cyclePhaseNow');
  if (phaseLbl) phaseLbl.textContent = phaseAtT(CYCLE_ANIM.t).name;
  CYCLE_ANIM.animId = requestAnimationFrame(cycleTick);
}
function startCycleAnim() {
  CYCLE_ANIM.playing = true;
  CYCLE_ANIM.lastFrame = 0;
  document.getElementById('cycle-play').style.display = 'none';
  document.getElementById('cycle-pause').style.display = '';
  document.getElementById('cycleArm').style.display = '';
  CYCLE_ANIM.animId = requestAnimationFrame(cycleTick);
}
function stopCycleAnim() {
  CYCLE_ANIM.playing = false;
  cancelAnimationFrame(CYCLE_ANIM.animId);
  document.getElementById('cycle-play').style.display = '';
  document.getElementById('cycle-pause').style.display = 'none';
}

/* ---- DNA REPLICATION FORK ANIMATION ---- */
const FORK_STATE = { t:0, playing:false, animId:null, lastFrame:0, okazaki:[] };
const FORK_STAGES = [
  { from:0,    to:0.10, name:'Helicase opens fork',          show:['hel'] },
  { from:0.10, to:0.30, name:'Leading strand: Pol III continuous synthesis', show:['hel','leading'] },
  { from:0.30, to:0.50, name:'Primase lays RNA primer (lagging)', show:['hel','leading','primase'] },
  { from:0.50, to:0.75, name:'Pol III extends Okazaki fragment', show:['hel','leading','primase','okazaki'] },
  { from:0.75, to:0.90, name:'Pol I replaces RNA primer with DNA', show:['hel','leading','okazaki','polI'] },
  { from:0.90, to:1.0,  name:'Ligase seals fragments → continuous lagging', show:['hel','leading','okazaki','polI','ligase'] },
];

function forkUpdate(t) {
  // Helicase moves right as t advances
  const hel = document.getElementById('forkHelicase');
  const helX = 400 + t * 280;
  if (hel) hel.setAttribute('transform', `translate(${(helX - 400)},0)`);
  // Helix shrinks as fork advances
  document.getElementById('forkHelixTop').setAttribute('x1', helX);
  document.getElementById('forkHelixBot').setAttribute('x1', helX);

  // Leading strand grows
  const leadingNew = document.getElementById('forkLeadingNew');
  const lTopY = 135;  // leading strand y
  const newRightX = 80 + (helX - 80) * Math.min(1, t * 1.5);
  leadingNew.setAttribute('x2', newRightX);
  const newRightY = lTopY + (newRightX - 80) * 0.125;
  leadingNew.setAttribute('y2', newRightY);
  // Pol III follows the leading strand growing edge
  const polLeading = document.getElementById('forkPolLeading');
  if (polLeading) {
    polLeading.setAttribute('cx', newRightX);
    polLeading.setAttribute('cy', newRightY);
  }
  // Find current stage
  let stage = FORK_STAGES[0];
  for (const s of FORK_STAGES) {
    if (t >= s.from && t < s.to) { stage = s; break; }
  }
  if (t >= 1.0) stage = FORK_STAGES[FORK_STAGES.length - 1];
  document.getElementById('forkStageTag').textContent = stage.name;

  // Show/hide elements based on stage
  const ids = { primase:'forkPrimase', polI:'forkPolI', ligase:'forkLigase' };
  Object.entries(ids).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (el) el.style.display = stage.show.includes(key) ? '' : 'none';
  });

  // Okazaki fragments: add a fragment as t crosses certain thresholds
  const okazakiGroup = document.getElementById('forkOkazakiGroup');
  if (okazakiGroup) {
    okazakiGroup.innerHTML = '';
    // Draw N fragments behind the fork (left side of fork)
    const numFragments = Math.min(5, Math.floor(t * 6));
    for (let i = 0; i < numFragments; i++) {
      const fragX1 = 80 + i * 60;
      const fragX2 = 80 + (i + 1) * 60 - 6;
      const yLagging = 240 - (fragX1 - 80) * 0.13;  // approximate lagging template y
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', fragX1); line.setAttribute('y1', yLagging);
      line.setAttribute('x2', fragX2); line.setAttribute('y2', yLagging - (fragX2 - fragX1) * 0.13);
      line.setAttribute('stroke', '#5FA874');
      line.setAttribute('stroke-width', '3.5');
      line.setAttribute('stroke-linecap', 'round');
      okazakiGroup.appendChild(line);
    }
  }
}

function forkTick(now) {
  if (!FORK_STATE.playing) return;
  if (!FORK_STATE.lastFrame) FORK_STATE.lastFrame = now;
  const dt = (now - FORK_STATE.lastFrame) / 1000;
  FORK_STATE.lastFrame = now;
  FORK_STATE.t += 0.10 * dt;  // ~10 sec full cycle
  if (FORK_STATE.t >= 1) FORK_STATE.t = 0;
  forkUpdate(FORK_STATE.t);
  FORK_STATE.animId = requestAnimationFrame(forkTick);
}
function forkStart() {
  FORK_STATE.playing = true; FORK_STATE.lastFrame = 0;
  document.getElementById('forkPlay').style.display = 'none';
  document.getElementById('forkPause').style.display = '';
  FORK_STATE.animId = requestAnimationFrame(forkTick);
}
function forkStop() {
  FORK_STATE.playing = false;
  cancelAnimationFrame(FORK_STATE.animId);
  document.getElementById('forkPlay').style.display = '';
  document.getElementById('forkPause').style.display = 'none';
}
function forkResetAll() {
  forkStop();
  FORK_STATE.t = 0;
  forkUpdate(0);
  document.getElementById('forkStageTag').textContent = 'Idle — press play';
}

function initDnaFork() {
  if (!document.getElementById('forkSvg')) return;
  forkUpdate(0);
  document.getElementById('forkPlay').addEventListener('click', forkStart);
  document.getElementById('forkPause').addEventListener('click', forkStop);
  document.getElementById('forkReset').addEventListener('click', forkResetAll);
}

/* ---- TRANSCRIPTION / TRANSLATION ANIMATION ---- */
const TX_STATE = { t:0, playing:false, animId:null, lastFrame:0 };
const TX_STAGES = [
  { from:0,    to:0.20, name:'Transcription: RNA Pol II reads template 3′→5′' },
  { from:0.20, to:0.32, name:'5′ cap added; transcription continues' },
  { from:0.32, to:0.45, name:'Splicing: introns excised, exons joined; poly-A tail added' },
  { from:0.45, to:0.55, name:'Mature mRNA exits nucleus through nuclear pore' },
  { from:0.55, to:0.65, name:'Ribosome assembles at AUG start codon' },
  { from:0.65, to:0.85, name:'Elongation: tRNA delivers aa to A site, peptide bond forms, translocation' },
  { from:0.85, to:1.0,  name:'Stop codon: release factor releases polypeptide' },
];
const TX_CODONS = ['AUG','GCC','UUU','AAG','UAA'];
const TX_AA = ['Met','Ala','Phe','Lys','STOP'];
const TX_CODON_X = [430, 490, 550, 610, 670];

function txUpdate(t) {
  // ----- TRANSCRIPTION PHASE (t < 0.45) -----
  // RNA polymerase glides 80 -> 340 across template
  const polEnd = Math.min(0.32, t) / 0.32;
  const polX = 80 + 260 * polEnd;
  const polEl = document.getElementById('txRnaPol');
  if (polEl) polEl.setAttribute('transform', `translate(${polX - 80},0)`);

  // pre-mRNA grows behind polymerase, dropping down toward y=240 then bending
  const preMrna = document.getElementById('txPreMrna');
  if (preMrna) {
    if (t < 0.32) {
      // grow from polX down and back left toward 60
      const dropY = 230;
      const leftX = Math.max(60, polX - 30);
      preMrna.setAttribute('d', `M ${polX} ${178} L ${polX} ${dropY} L ${leftX} ${dropY}`);
    } else {
      preMrna.setAttribute('d', `M 60 230 L 340 230`);
    }
  }

  // 5' cap appears around t=0.20
  const cap = document.getElementById('txCap');
  const capLabel = document.getElementById('txCapLabel');
  if (cap && capLabel) {
    const showCap = t >= 0.20 && t < 0.50;
    cap.style.display = showCap ? '' : 'none';
    capLabel.style.display = showCap ? '' : 'none';
    cap.setAttribute('cx', 60);
    cap.setAttribute('cy', 230);
    capLabel.setAttribute('x', 60);
    capLabel.setAttribute('y', 248);
  }

  // ----- SPLICING (0.32 - 0.45) -----
  const introns = document.getElementById('txIntrons');
  if (introns) introns.style.display = (t >= 0.32 && t < 0.45) ? '' : 'none';

  // Mature mRNA shows after splicing (0.40+)
  const matureMrna = document.getElementById('txMatureMrna');
  const polyA = document.getElementById('txPolyA');
  if (matureMrna) {
    if (t >= 0.40 && t < 0.55) {
      matureMrna.setAttribute('x1', 60); matureMrna.setAttribute('y1', 260);
      matureMrna.setAttribute('x2', 320); matureMrna.setAttribute('y2', 260);
      if (polyA) polyA.style.display = '';
    } else {
      matureMrna.setAttribute('x1', 60); matureMrna.setAttribute('x2', 60);
      if (polyA) polyA.style.display = 'none';
    }
  }

  // ----- mRNA EXPORT (0.45 - 0.55) -----
  const cyto = document.getElementById('txCytoMrnaGroup');
  if (cyto) cyto.style.display = (t >= 0.55) ? '' : 'none';

  // ----- TRANSLATION (0.55 - 1.0) -----
  const ribosome = document.getElementById('txRibosome');
  const riboShow = t >= 0.55;
  if (ribosome) ribosome.style.display = riboShow ? '' : 'none';

  // Ribosome moves codon-by-codon during elongation (0.65 - 0.85)
  let codonIndex = 0;
  if (t >= 0.65 && t < 0.85) {
    codonIndex = Math.min(4, Math.floor((t - 0.65) / 0.05));
  } else if (t >= 0.85) {
    codonIndex = 4;
  }
  if (riboShow) {
    const targetX = TX_CODON_X[codonIndex];
    const riboLarge = document.getElementById('txRiboLarge');
    const riboSmall = document.getElementById('txRiboSmall');
    const riboLabel = document.getElementById('txRiboLabel');
    if (riboLarge) riboLarge.setAttribute('cx', targetX);
    if (riboSmall) riboSmall.setAttribute('cx', targetX);
    if (riboLabel) riboLabel.setAttribute('x', targetX);
  }

  // tRNA hovers in A site for codons 0..3, hidden at stop codon
  const trnaA = document.getElementById('txTrnaA');
  const trnaALabel = document.getElementById('txTrnaALabel');
  if (trnaA && trnaALabel) {
    const showTrna = t >= 0.60 && codonIndex < 4;
    trnaA.style.display = showTrna ? '' : 'none';
    trnaALabel.style.display = showTrna ? '' : 'none';
    if (showTrna) {
      const cx = TX_CODON_X[codonIndex] + 10;
      trnaA.setAttribute('transform', `translate(${cx - 510},0)`);
      trnaALabel.setAttribute('x', cx);
      trnaALabel.textContent = TX_AA[codonIndex] || 'Met';
    }
  }

  // Polypeptide chain grows: amino acids appear as small circles above ribosome
  const polyGroup = document.getElementById('txPolyGroup');
  if (polyGroup) {
    polyGroup.innerHTML = '';
    if (riboShow) {
      const numAA = Math.min(4, codonIndex + (t >= 0.85 ? 1 : 0));
      for (let i = 0; i < numAA; i++) {
        const cx = TX_CODON_X[0] + i * 22;
        const cy = 220 - (i % 2) * 6;
        const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        c.setAttribute('cx', cx);
        c.setAttribute('cy', cy);
        c.setAttribute('r', 9);
        c.setAttribute('fill', '#5FA874');
        c.setAttribute('stroke', '#1B3A2D');
        c.setAttribute('stroke-width', '1.5');
        polyGroup.appendChild(c);
        const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        label.setAttribute('x', cx);
        label.setAttribute('y', cy + 3);
        label.setAttribute('text-anchor', 'middle');
        label.setAttribute('font-size', '8');
        label.setAttribute('font-weight', '700');
        label.setAttribute('fill', '#fff');
        label.textContent = TX_AA[i] || '';
        polyGroup.appendChild(label);
        // Bond line from previous aa
        if (i > 0) {
          const prevX = TX_CODON_X[0] + (i - 1) * 22;
          const prevY = 220 - ((i - 1) % 2) * 6;
          const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
          line.setAttribute('x1', prevX); line.setAttribute('y1', prevY);
          line.setAttribute('x2', cx); line.setAttribute('y2', cy);
          line.setAttribute('stroke', '#1B3A2D');
          line.setAttribute('stroke-width', '1.5');
          polyGroup.appendChild(line);
        }
      }
    }
  }

  // Release factor at stop codon
  const rf = document.getElementById('txReleaseFactor');
  if (rf) rf.style.display = (t >= 0.85) ? '' : 'none';

  // Stage tag
  let stage = TX_STAGES[0];
  for (const s of TX_STAGES) {
    if (t >= s.from && t < s.to) { stage = s; break; }
  }
  if (t >= 1.0) stage = TX_STAGES[TX_STAGES.length - 1];
  const tag = document.getElementById('txStageTag');
  if (tag) tag.textContent = stage.name;
}

function txTick(now) {
  if (!TX_STATE.playing) return;
  if (!TX_STATE.lastFrame) TX_STATE.lastFrame = now;
  const dt = (now - TX_STATE.lastFrame) / 1000;
  TX_STATE.lastFrame = now;
  TX_STATE.t += 0.07 * dt;  // ~14 sec full cycle
  if (TX_STATE.t >= 1) TX_STATE.t = 0;
  txUpdate(TX_STATE.t);
  TX_STATE.animId = requestAnimationFrame(txTick);
}
function txStart() {
  TX_STATE.playing = true; TX_STATE.lastFrame = 0;
  document.getElementById('txPlay').style.display = 'none';
  document.getElementById('txPause').style.display = '';
  TX_STATE.animId = requestAnimationFrame(txTick);
}
function txStop() {
  TX_STATE.playing = false;
  cancelAnimationFrame(TX_STATE.animId);
  document.getElementById('txPlay').style.display = '';
  document.getElementById('txPause').style.display = 'none';
}
function txResetAll() {
  txStop();
  TX_STATE.t = 0;
  txUpdate(0);
  const tag = document.getElementById('txStageTag');
  if (tag) tag.textContent = 'Idle — press play';
}

function initTranscription() {
  if (!document.getElementById('txSvg')) return;
  txUpdate(0);
  document.getElementById('txPlay').addEventListener('click', txStart);
  document.getElementById('txPause').addEventListener('click', txStop);
  document.getElementById('txReset').addEventListener('click', txResetAll);
}

/* ---- ACTION POTENTIAL ANIMATION ---- */
const AP_STATE = { t:0, playing:false, animId:null, lastFrame:0, points:[] };
const AP_X0 = 80, AP_X1 = 700, AP_PLOT_W = AP_X1 - AP_X0;
// V(t) Hodgkin-Huxley-shaped voltage (t in 0-1, full sweep ≈ 5 ms displayed)
function apVoltageAt(t) {
  // resting -70, threshold reached at t=0.18, peak +30 at t=0.30, repol back to -70 at t=0.55, undershoot -90 at t=0.65, return rest by 1.0
  if (t < 0.15) return -70 + (t / 0.15) * 5;          // -70 → -65
  if (t < 0.20) return -65 + ((t - 0.15) / 0.05) * 10; // -65 → -55 threshold
  if (t < 0.32) return -55 + ((t - 0.20) / 0.12) * 85; // -55 → +30 spike
  if (t < 0.55) return 30 - ((t - 0.32) / 0.23) * 100; // +30 → -70
  if (t < 0.70) return -70 - ((t - 0.55) / 0.15) * 20; // -70 → -90 hyperpolarization
  if (t < 1.0)  return -90 + ((t - 0.70) / 0.30) * 20; // -90 → -70
  return -70;
}
function apMvToY(mv) {
  // Map mV: +30 → y=70, -70 → y=155, -90 → y=225 (linear)
  // slope: 1 mV = (155 - 70) / (-70 - 30) = -0.85 per mV
  return 155 + (-70 - mv) * 0.85;
}
function apStageFor(t) {
  if (t < 0.15) return 'Resting (-70 mV) · K⁺ leak + Na/K pump';
  if (t < 0.20) return 'Stimulus → membrane depolarizing toward threshold';
  if (t < 0.32) return 'Depolarization · VG Na⁺ open · Na⁺ rushes IN';
  if (t < 0.45) return 'Peak (+30 mV) · Na⁺ inactivates · K⁺ opens';
  if (t < 0.55) return 'Repolarization · K⁺ rushes OUT';
  if (t < 0.70) return 'Hyperpolarization (-90) · K⁺ closes slowly · refractory';
  return 'Return to rest · Na/K pump restores gradient';
}
function apChannelStates(t) {
  let na = 'closed', k = 'closed';
  if (t < 0.20) { na = 'closed'; k = 'closed (leak)'; }
  else if (t < 0.32) { na = 'OPEN'; k = 'closed'; }
  else if (t < 0.45) { na = 'inactivated'; k = 'opening'; }
  else if (t < 0.55) { na = 'inactivated'; k = 'OPEN'; }
  else if (t < 0.70) { na = 'closed'; k = 'closing'; }
  else { na = 'closed'; k = 'closed (leak)'; }
  return { na, k };
}
function apUpdate(t) {
  // Build trace points (cumulative until current t)
  const pts = [];
  const SAMPLES = 80;
  const upTo = Math.min(1, t);
  for (let i = 0; i <= SAMPLES * upTo; i++) {
    const tt = i / SAMPLES;
    const x = AP_X0 + tt * AP_PLOT_W;
    const y = apMvToY(apVoltageAt(tt));
    pts.push(`${x},${y}`);
  }
  const trace = document.getElementById('apTrace');
  if (trace) trace.setAttribute('points', pts.join(' '));

  // Marker
  const mv = apVoltageAt(t);
  const markerX = AP_X0 + t * AP_PLOT_W;
  const markerY = apMvToY(mv);
  const marker = document.getElementById('apMarker');
  if (marker) { marker.setAttribute('cx', markerX); marker.setAttribute('cy', markerY); }

  // Channel states
  const { na, k } = apChannelStates(t);
  const naEl = document.getElementById('apNaState');
  const kEl  = document.getElementById('apKState');
  if (naEl) naEl.textContent = na;
  if (kEl)  kEl.textContent  = k;
  // Color the channel boxes
  const naBox = document.querySelector('#apNaChannel rect');
  const kBox  = document.querySelector('#apKChannel rect');
  if (naBox) naBox.setAttribute('fill', na === 'OPEN' ? '#fde2dc' : '#fff');
  if (kBox)  kBox.setAttribute('fill', k === 'OPEN' ? '#dceede' : '#fff');

  // Ion flow arrows
  const naFlow = document.getElementById('apNaFlow');
  const kFlow  = document.getElementById('apKFlow');
  if (naFlow) naFlow.style.display = na === 'OPEN' ? '' : 'none';
  if (kFlow)  kFlow.style.display  = k === 'OPEN' ? '' : 'none';

  // Stage tag
  const tag = document.getElementById('apStageTag');
  if (tag) tag.textContent = apStageFor(t);
}
function apTick(now) {
  if (!AP_STATE.playing) return;
  if (!AP_STATE.lastFrame) AP_STATE.lastFrame = now;
  const dt = (now - AP_STATE.lastFrame) / 1000;
  AP_STATE.lastFrame = now;
  AP_STATE.t += 0.12 * dt;  // ~8 sec per cycle
  if (AP_STATE.t >= 1) AP_STATE.t = 0;
  apUpdate(AP_STATE.t);
  AP_STATE.animId = requestAnimationFrame(apTick);
}
function apStart() {
  AP_STATE.playing = true; AP_STATE.lastFrame = 0;
  document.getElementById('apPlay').style.display = 'none';
  document.getElementById('apPause').style.display = '';
  AP_STATE.animId = requestAnimationFrame(apTick);
}
function apStop() {
  AP_STATE.playing = false;
  cancelAnimationFrame(AP_STATE.animId);
  document.getElementById('apPlay').style.display = '';
  document.getElementById('apPause').style.display = 'none';
}
function apResetAll() {
  apStop();
  AP_STATE.t = 0;
  apUpdate(0);
  const tag = document.getElementById('apStageTag');
  if (tag) tag.textContent = 'Idle — press play';
}
function initActionPotential() {
  if (!document.getElementById('apSvg')) return;
  apUpdate(0);
  document.getElementById('apPlay').addEventListener('click', apStart);
  document.getElementById('apPause').addEventListener('click', apStop);
  document.getElementById('apReset').addEventListener('click', apResetAll);
}

/* ---- RESPIRATORY VENTILATION ANIMATION ---- */
const VENT_STATE = { t:0, playing:false, animId:null, lastFrame:0 };
function ventUpdate(t) {
  // sinusoidal cycle: t in 0..1 = one full breath
  // 0..0.5 = inspiration (volume rises), 0.5..1 = expiration
  const phase = Math.sin(t * 2 * Math.PI - Math.PI/2);  // -1 at t=0, +1 at t=0.5, -1 at t=1
  // volume: small at t=0/1, max at t=0.5
  const volNorm = (phase + 1) / 2;  // 0..1
  // pressure: opposite (drops during inspiration)
  const pressNorm = -phase * 0.6;  // -0.6 at peak inspire, +0.6 at peak expire

  // Lungs scale with volume
  const lungR = 70 + volNorm * 25;
  const lungL = document.getElementById('ventLungL');
  const lungRel = document.getElementById('ventLungR');
  if (lungL) lungL.setAttribute('ry', lungR);
  if (lungRel) lungRel.setAttribute('ry', lungR);

  // Diaphragm: domed when expiring, flat when inspiring
  const diaphragm = document.getElementById('ventDiaphragm');
  if (diaphragm) {
    const dipY = 290 + (1 - volNorm) * 25;  // higher (smaller y) when contracted-flat
    const flatY = 290 - volNorm * 5;
    diaphragm.setAttribute('d', `M 130 ${flatY} Q 280 ${dipY} 430 ${flatY}`);
  }

  // Air flow arrow direction
  const airFlow = document.getElementById('ventAirFlow');
  const airLabel = document.getElementById('ventAirLabel');
  if (airFlow && airLabel) {
    if (t < 0.5) {
      airFlow.setAttribute('y1', 20); airFlow.setAttribute('y2', 40);
      airLabel.textContent = 'in';
      airLabel.setAttribute('fill', '#5FA874');
      airFlow.setAttribute('stroke', '#5FA874');
    } else {
      airFlow.setAttribute('y1', 40); airFlow.setAttribute('y2', 20);
      airLabel.textContent = 'out';
      airLabel.setAttribute('fill', '#C25B3F');
      airFlow.setAttribute('stroke', '#C25B3F');
    }
  }

  // Pressure/volume traces (within plot width 200, height 200)
  const N = 80;
  const upTo = Math.floor(N * t);
  let volPts = '', pressPts = '';
  for (let i = 0; i <= upTo; i++) {
    const tt = i / N;
    const ph = Math.sin(tt * 2 * Math.PI - Math.PI/2);
    const vNorm = (ph + 1) / 2;
    const pNorm = -ph * 0.6;
    const x = tt * 200;
    const yV = 120 - vNorm * 80;     // green: volume above midline at peak
    const yP = 120 - pNorm * 80;     // orange: pressure below midline during inspire
    volPts += `${x},${yV} `;
    pressPts += `${x},${yP} `;
  }
  const volTrace = document.getElementById('ventVolTrace');
  const pressTrace = document.getElementById('ventPressTrace');
  if (volTrace) volTrace.setAttribute('points', volPts.trim());
  if (pressTrace) pressTrace.setAttribute('points', pressPts.trim());

  const xMark = t * 200;
  const volMarker = document.getElementById('ventVolMarker');
  const pressMarker = document.getElementById('ventPressMarker');
  if (volMarker) { volMarker.setAttribute('cx', xMark); volMarker.setAttribute('cy', 120 - volNorm * 80); }
  if (pressMarker) { pressMarker.setAttribute('cx', xMark); pressMarker.setAttribute('cy', 120 - pressNorm * 80); }

  // Stage tag
  const tag = document.getElementById('ventStageTag');
  let label;
  if (t < 0.10) label = 'Diaphragm starting to contract — early inspiration';
  else if (t < 0.40) label = 'Inspiration · diaphragm flattens · V↑ · P↓ · air IN';
  else if (t < 0.55) label = 'Peak lung volume · brief pause';
  else if (t < 0.85) label = 'Expiration · diaphragm relaxes · V↓ · P↑ · air OUT';
  else label = 'End-expiration · resting volume';
  if (tag) tag.textContent = label;
}
function ventTick(now) {
  if (!VENT_STATE.playing) return;
  if (!VENT_STATE.lastFrame) VENT_STATE.lastFrame = now;
  const dt = (now - VENT_STATE.lastFrame) / 1000;
  VENT_STATE.lastFrame = now;
  VENT_STATE.t += 0.20 * dt;  // ~5 sec per breath
  if (VENT_STATE.t >= 1) VENT_STATE.t = 0;
  ventUpdate(VENT_STATE.t);
  VENT_STATE.animId = requestAnimationFrame(ventTick);
}
function ventStart() {
  VENT_STATE.playing = true; VENT_STATE.lastFrame = 0;
  document.getElementById('ventPlay').style.display = 'none';
  document.getElementById('ventPause').style.display = '';
  VENT_STATE.animId = requestAnimationFrame(ventTick);
}
function ventStop() {
  VENT_STATE.playing = false;
  cancelAnimationFrame(VENT_STATE.animId);
  document.getElementById('ventPlay').style.display = '';
  document.getElementById('ventPause').style.display = 'none';
}
function ventResetAll() {
  ventStop();
  VENT_STATE.t = 0;
  ventUpdate(0);
  const tag = document.getElementById('ventStageTag');
  if (tag) tag.textContent = 'Idle — press play';
}
function initVentilation() {
  if (!document.getElementById('ventSvg')) return;
  ventUpdate(0);
  document.getElementById('ventPlay').addEventListener('click', ventStart);
  document.getElementById('ventPause').addEventListener('click', ventStop);
  document.getElementById('ventReset').addEventListener('click', ventResetAll);
}

/* ---- MEMBRANE TRANSPORT SIM ---- */
const MEM_MODES = {
  diffusion:   { label:'Simple diffusion', proteins:[], outBar:100, inBar:30, particles:'O₂/CO₂/lipids',
                 particleColor:'#5FA874', flow:'down', atp:false, info:'<b>What:</b> small nonpolar molecules (O₂, CO₂, steroids) cross directly through the bilayer.<br><b>Driving force:</b> concentration gradient (high → low).<br><b>Cost:</b> 0 ATP. Passive.<br><b>Selectivity:</b> determined by lipid solubility.' },
  osmosis:     { label:'Osmosis (water)', proteins:[], outBar:30, inBar:100, particles:'H₂O',
                 particleColor:'#5cabe6', flow:'up', atp:false, info:'<b>What:</b> water moves through aquaporins or directly through bilayer.<br><b>Driving force:</b> water moves toward higher solute concentration (lower water potential).<br><b>Cost:</b> 0 ATP.<br><b>Tonicity:</b> hypertonic environment → cell shrinks; hypotonic → cell swells.' },
  facilitated: { label:'Facilitated diffusion', proteins:['memChannel','memCarrier'], outBar:100, inBar:30, particles:'glucose, ions',
                 particleColor:'#c19a3e', flow:'down', atp:false, info:'<b>What:</b> polar molecules and ions cross via channels (e.g., aquaporins, K+ leak) or carriers (e.g., GLUT).<br><b>Driving force:</b> still concentration gradient.<br><b>Cost:</b> 0 ATP. Passive but protein-mediated.<br><b>Saturable:</b> finite number of carriers → reaches Vmax (Michaelis-Menten kinetics).' },
  primary:     { label:'Primary active (Na/K ATPase)', proteins:['memPump'], outBar:30, inBar:100, particles:'3 Na+ out / 2 K+ in',
                 particleColor:'#C25B3F', flow:'against', atp:true, info:'<b>What:</b> Na/K pump moves <b>3 Na⁺ OUT</b> and <b>2 K⁺ IN</b> per ATP hydrolyzed.<br><b>Driving force:</b> ATP hydrolysis (chemical energy).<br><b>Cost:</b> 1 ATP per cycle.<br><b>Result:</b> creates and maintains electrochemical gradient (basis of resting membrane potential, secondary active transport).' },
  secondary:   { label:'Secondary active (SGLT)', proteins:['memCotrans'], outBar:100, inBar:30, particles:'glucose + Na+ symport',
                 particleColor:'#5FA874', flow:'cotransport', atp:false, info:'<b>What:</b> co-transporter rides the Na⁺ gradient (set up by Na/K pump) to drag glucose IN against its gradient.<br><b>Driving force:</b> Na⁺ flowing down its gradient.<br><b>Cost:</b> 0 ATP <i>directly</i>, but <b>indirectly</b> uses ATP that built the Na⁺ gradient.<br><b>Examples:</b> SGLT (Na/glucose symport), Na/Ca antiport, NHE.' },
  endo:        { label:'Endocytosis', proteins:['memVesicle'], outBar:80, inBar:40, particles:'large particles',
                 particleColor:'#8a5a8c', flow:'engulf', atp:true, info:'<b>What:</b> membrane invaginates and pinches off, taking material into the cell as a vesicle.<br><b>Subtypes:</b> phagocytosis (cell eating, big particles), pinocytosis (cell drinking, fluid), receptor-mediated (specific, e.g., LDL).<br><b>Cost:</b> ATP needed to remodel membrane and cytoskeleton.' },
  exo:         { label:'Exocytosis', proteins:['memVesicle'], outBar:40, inBar:80, particles:'secreted product',
                 particleColor:'#a378a5', flow:'release', atp:true, info:'<b>What:</b> intracellular vesicle fuses with plasma membrane, releasing contents to extracellular space.<br><b>Examples:</b> neurotransmitter release at synapse, hormone secretion, antibody release.<br><b>Cost:</b> ATP for vesicle trafficking + Ca²⁺ trigger for fusion.' },
};
const MEM_STATE = { mode:null, animId:null, particles:[] };

function memSetMode(mode) {
  const m = MEM_MODES[mode];
  if (!m) return;
  MEM_STATE.mode = mode;

  // Toggle proteins
  ['memChannel','memCarrier','memPump','memCotrans','memVesicle'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = m.proteins.includes(id) ? '' : 'none';
  });

  // Update gradient bars
  document.getElementById('memOutBar').setAttribute('width', m.outBar);
  document.getElementById('memInBar').setAttribute('width', m.inBar);

  // Update info
  document.getElementById('memInfo').innerHTML =
    `<p style="margin-bottom:8px"><b>${m.label}</b></p><p>${m.info}</p>`;

  // Update stage tag
  document.getElementById('memStageTag').textContent =
    `${m.label} · ${m.atp ? 'requires ATP' : 'passive (no ATP)'}`;

  // Highlight selected button
  document.querySelectorAll('[data-mem-mode]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.memMode === mode);
  });

  // Restart particle animation
  memInitParticles(mode);
}

function memInitParticles(mode) {
  const m = MEM_MODES[mode];
  const group = document.getElementById('memParticles');
  if (!group) return;
  group.innerHTML = '';
  MEM_STATE.particles = [];
  cancelAnimationFrame(MEM_STATE.animId);

  // Spawn particles based on mode
  const numParticles = (mode === 'endo' || mode === 'exo') ? 6 : 14;
  for (let i = 0; i < numParticles; i++) {
    const startSide = (mode === 'exo' || mode === 'primary') ? 'in' : 'out';
    let x, y;
    if (mode === 'endo' || mode === 'exo') {
      x = 250 + Math.random() * 300;
      y = startSide === 'out' ? 60 + Math.random() * 100 : 280 + Math.random() * 100;
    } else if (i < numParticles / 2) {
      // half outside (above bilayer)
      x = 60 + Math.random() * 680;
      y = 60 + Math.random() * 110;
    } else {
      // half inside
      x = 60 + Math.random() * 680;
      y = 260 + Math.random() * 110;
    }
    const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    c.setAttribute('cx', x);
    c.setAttribute('cy', y);
    c.setAttribute('r', mode === 'osmosis' ? 4 : 5);
    c.setAttribute('fill', m.particleColor);
    c.setAttribute('stroke', '#1B3A2D');
    c.setAttribute('stroke-width', '0.8');
    group.appendChild(c);
    const vx = (Math.random() - 0.5) * 0.6;
    const vy = (Math.random() - 0.5) * 0.6;
    MEM_STATE.particles.push({ el: c, x, y, vx, vy, side: y < 200 ? 'out' : 'in' });
  }
  memTick();
}

function memTick() {
  const m = MEM_MODES[MEM_STATE.mode];
  if (!m) return;
  for (const p of MEM_STATE.particles) {
    p.x += p.vx; p.y += p.vy;
    // bounce off side walls
    if (p.x < 50) p.vx = Math.abs(p.vx);
    if (p.x > 750) p.vx = -Math.abs(p.vx);

    // Membrane crossing logic — simple diffusion / osmosis: any time hits membrane mid, allow crossing
    if (m.flow === 'down') {
      // mostly outside → inside (with some back)
      if (p.side === 'out' && p.y > 190) {
        p.y += 0.6; if (p.y > 250) p.side = 'in';
      } else if (p.side === 'in' && p.y < 240) {
        if (Math.random() < 0.05) p.y += 0.4;
      }
      if (p.side === 'out' && p.y < 60) p.vy = Math.abs(p.vy);
      if (p.side === 'in'  && p.y > 380) p.vy = -Math.abs(p.vy);
    } else if (m.flow === 'up') {
      // osmosis: water flows toward higher solute (intracellular bar 100 = high solute = water in)
      if (p.side === 'out' && p.y > 180) {
        p.y += 0.5; if (p.y > 250) p.side = 'in';
      }
      if (p.side === 'in'  && p.y > 380) p.vy = -Math.abs(p.vy);
      if (p.side === 'out' && p.y < 60)  p.vy = Math.abs(p.vy);
    } else if (m.flow === 'against') {
      // Na/K pump: Na (out 30, in 100 originally) → pumped OUT (against gradient)
      // Show particles moving from inside to outside near the pump
      if (p.side === 'in' && p.x > 540 && p.x < 600 && p.y > 230) {
        p.y -= 0.7; if (p.y < 175) p.side = 'out';
      }
      if (p.side === 'out' && p.y < 60) p.vy = Math.abs(p.vy);
      if (p.side === 'in'  && p.y > 380) p.vy = -Math.abs(p.vy);
      // bounce off membrane in non-pump regions
      if ((p.x < 540 || p.x > 600) && p.y > 180 && p.y < 250) {
        p.y = p.side === 'out' ? 180 : 250;
        p.vy = -p.vy;
      }
    } else if (m.flow === 'cotransport') {
      // SGLT — at x in [640,700]
      if (p.side === 'out' && p.x > 640 && p.x < 700 && p.y > 180) {
        p.y += 0.6; if (p.y > 250) p.side = 'in';
      }
      if ((p.x < 640 || p.x > 700) && p.y > 180 && p.y < 250) {
        p.y = p.side === 'out' ? 180 : 250;
        p.vy = -p.vy;
      }
      if (p.side === 'out' && p.y < 60) p.vy = Math.abs(p.vy);
      if (p.side === 'in'  && p.y > 380) p.vy = -Math.abs(p.vy);
    } else if (m.flow === 'engulf') {
      // particles drift toward vesicle (400, 320)
      const dx = 400 - p.x, dy = 320 - p.y;
      const d = Math.sqrt(dx*dx + dy*dy);
      if (d > 4) { p.x += dx / d * 0.6; p.y += dy / d * 0.6; }
    } else if (m.flow === 'release') {
      // particles drift away from vesicle outward
      const dx = p.x - 400, dy = p.y - 100;
      const d = Math.sqrt(dx*dx + dy*dy);
      if (d > 0) { p.x += dx / d * 0.4; p.y += dy / d * 0.4; }
    }

    p.el.setAttribute('cx', p.x);
    p.el.setAttribute('cy', p.y);
  }
  MEM_STATE.animId = requestAnimationFrame(memTick);
}

function initMembraneTransport() {
  if (!document.getElementById('memSvg')) return;
  // Phospholipid heads
  const heads = document.getElementById('memHeads');
  if (heads && heads.childNodes.length === 0) {
    for (let i = 0; i < 36; i++) {
      const x = 50 + i * 20;
      const top = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      top.setAttribute('cx', x); top.setAttribute('cy', 190); top.setAttribute('r', 5);
      top.setAttribute('fill', '#c19a3e'); top.setAttribute('stroke', '#1B3A2D'); top.setAttribute('stroke-width', '0.8');
      heads.appendChild(top);
      const bot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      bot.setAttribute('cx', x); bot.setAttribute('cy', 240); bot.setAttribute('r', 5);
      bot.setAttribute('fill', '#c19a3e'); bot.setAttribute('stroke', '#1B3A2D'); bot.setAttribute('stroke-width', '0.8');
      heads.appendChild(bot);
    }
  }
  document.querySelectorAll('[data-mem-mode]').forEach(btn => {
    btn.addEventListener('click', () => memSetMode(btn.dataset.memMode));
  });
  memSetMode('diffusion');
}

