function sigYForLoc(loc) {
  if (loc === 'out')  return 80;
  if (loc === 'mem')  return 140;
  if (loc === 'cyto') return 220;
  if (loc === 'nuc')  return 380;
  return 220;
}

function sigSetMode(mode) {
  const m = SIG_MODES[mode];
  if (!m) return;
  const group = document.getElementById('sigNodes');
  group.innerHTML = '';
  // Nucleus background (if any node is in nuc)
  const hasNuc = m.nodes.some(n => n.loc === 'nuc');
  if (hasNuc) {
    const nuc = document.createElementNS('http://www.w3.org/2000/svg', 'ellipse');
    nuc.setAttribute('cx', 660);
    nuc.setAttribute('cy', 380);
    nuc.setAttribute('rx', 130);
    nuc.setAttribute('ry', 70);
    nuc.setAttribute('fill', '#f7f0e1');
    nuc.setAttribute('stroke', '#1B3A2D');
    nuc.setAttribute('stroke-width', '2');
    group.appendChild(nuc);
    const nucL = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    nucL.setAttribute('x', 660); nucL.setAttribute('y', 320);
    nucL.setAttribute('text-anchor', 'middle');
    nucL.setAttribute('font-size', '10');
    nucL.setAttribute('font-weight', '700');
    nucL.setAttribute('fill', '#1B3A2D');
    nucL.textContent = 'NUCLEUS';
    group.appendChild(nucL);
  }
  // Draw arrows between nodes first (so circles overlay)
  for (let i = 0; i < m.nodes.length - 1; i++) {
    const a = m.nodes[i], b = m.nodes[i + 1];
    const ay = sigYForLoc(a.loc), by = sigYForLoc(b.loc);
    const ln = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    ln.setAttribute('x1', a.x + 18); ln.setAttribute('y1', ay);
    ln.setAttribute('x2', b.x - 18); ln.setAttribute('y2', by);
    ln.setAttribute('stroke', '#1B3A2D');
    ln.setAttribute('stroke-width', '1.5');
    ln.setAttribute('marker-end', 'url(#sig-arrow)');
    group.appendChild(ln);
  }
  // Draw nodes
  m.nodes.forEach((n, idx) => {
    const y = sigYForLoc(n.loc);
    const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    c.setAttribute('cx', n.x); c.setAttribute('cy', y);
    c.setAttribute('r', 18);
    c.setAttribute('fill', n.color);
    c.setAttribute('stroke', '#1B3A2D');
    c.setAttribute('stroke-width', '2');
    c.setAttribute('class', 'sig-node');
    c.style.cursor = 'pointer';
    group.appendChild(c);
    const num = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    num.setAttribute('x', n.x); num.setAttribute('y', y + 4);
    num.setAttribute('text-anchor', 'middle');
    num.setAttribute('font-size', '11');
    num.setAttribute('font-weight', '700');
    num.setAttribute('fill', '#fff');
    num.textContent = (idx + 1);
    group.appendChild(num);
    const lbl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    lbl.setAttribute('x', n.x); lbl.setAttribute('y', y + 38);
    lbl.setAttribute('text-anchor', 'middle');
    lbl.setAttribute('font-size', '9');
    lbl.setAttribute('font-weight', '700');
    lbl.setAttribute('fill', '#1B3A2D');
    lbl.textContent = n.label;
    group.appendChild(lbl);
  });

  document.getElementById('sigInfo').innerHTML =
    `<p style="margin-bottom:8px"><b>${m.label}</b></p><p>${m.info}</p>`;
  document.getElementById('sigStageTag').textContent = m.label;
  document.querySelectorAll('[data-sig-mode]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.sigMode === mode);
  });
}

function initSignalTransduction() {
  if (!document.getElementById('sigSvg')) return;
  document.querySelectorAll('[data-sig-mode]').forEach(btn => {
    btn.addEventListener('click', () => sigSetMode(btn.dataset.sigMode));
  });
  sigSetMode('gpcr');
}

/* ---- MUTATION SIMULATOR ---- */
const CODON_TABLE = {
  AUG:'Met', UUU:'Phe', UUC:'Phe', UUA:'Leu', UUG:'Leu', CUU:'Leu', CUC:'Leu', CUA:'Leu', CUG:'Leu',
  AUU:'Ile', AUC:'Ile', AUA:'Ile', GUU:'Val', GUC:'Val', GUA:'Val', GUG:'Val',
  UCU:'Ser', UCC:'Ser', UCA:'Ser', UCG:'Ser', AGU:'Ser', AGC:'Ser',
  CCU:'Pro', CCC:'Pro', CCA:'Pro', CCG:'Pro', ACU:'Thr', ACC:'Thr', ACA:'Thr', ACG:'Thr',
  GCU:'Ala', GCC:'Ala', GCA:'Ala', GCG:'Ala', UAU:'Tyr', UAC:'Tyr',
  CAU:'His', CAC:'His', CAA:'Gln', CAG:'Gln', AAU:'Asn', AAC:'Asn',
  AAA:'Lys', AAG:'Lys', GAU:'Asp', GAC:'Asp', GAA:'Glu', GAG:'Glu',
  UGU:'Cys', UGC:'Cys', UGG:'Trp', CGU:'Arg', CGC:'Arg', CGA:'Arg', CGG:'Arg', AGA:'Arg', AGG:'Arg',
  GGU:'Gly', GGC:'Gly', GGA:'Gly', GGG:'Gly',
  UAA:'STOP', UAG:'STOP', UGA:'STOP',
};
const ORIG_MRNA = 'AUGCCCUUUAAAGGCUAA';
function translateMrna(mrna) {
  const codons = mrna.match(/.{1,3}/g) || [];
  return codons.map(c => CODON_TABLE[c] || '?').join(' - ');
}

const MUTATIONS = {
  silent: {
    label:'Silent mutation',
    apply: m => m.slice(0, 5) + 'A' + m.slice(6),  // CCC → CCA (still Pro)
    effect:'<b>Silent mutation.</b> 3rd codon position changed (C→A in CCA codon) but still codes for Proline. <b>No effect</b> on protein. Wobble position degeneracy of the genetic code allows this. Most common type of synonymous variant.'
  },
  missense: {
    label:'Missense mutation',
    apply: m => m.slice(0, 4) + 'U' + m.slice(5),  // CCC → CUC (Pro → Leu)
    effect:'<b>Missense mutation.</b> Single nucleotide change → different amino acid (Pro → Leu). Effect varies: <b>conservative</b> (similar properties, often tolerated) vs <b>non-conservative</b> (different properties, often damaging). Classic example: <b>sickle cell anemia</b> — single Glu→Val swap in β-globin causes hemoglobin to polymerize.'
  },
  nonsense: {
    label:'Nonsense mutation',
    apply: m => m.slice(0, 3) + 'UAA' + m.slice(6),  // CCC → UAA (Pro → STOP)
    effect:'<b>Nonsense mutation.</b> Codon converted to <b>STOP</b> (UAA, UAG, or UGA). Premature termination → <b>truncated, usually nonfunctional protein</b>. Often triggers nonsense-mediated decay (NMD) of the mRNA. Examples: many forms of Duchenne muscular dystrophy, cystic fibrosis G542X.'
  },
  frameshift_ins: {
    label:'Frameshift insertion (+1)',
    apply: m => m.slice(0, 3) + 'A' + m.slice(3),  // insert A after AUG
    effect:'<b>Frameshift mutation (insertion).</b> +1 nucleotide shifts the reading frame for ALL downstream codons. Original Pro-Phe-Lys-Gly-STOP becomes a completely different amino acid sequence, usually hitting a premature stop codon. <b>Almost always devastating</b> — produces a nonfunctional protein. Examples: BRCA1 frameshifts, Tay-Sachs, many CF mutations.'
  },
  frameshift_del: {
    label:'Frameshift deletion (-1)',
    apply: m => m.slice(0, 3) + m.slice(4),  // remove first C of CCC
    effect:'<b>Frameshift mutation (deletion).</b> -1 nucleotide shifts reading frame. Same logic as insertion — all downstream codons change, nearly always producing a nonfunctional protein. <b>ΔF508 in CFTR</b> (cystic fibrosis) is a 3-nt deletion that is in-frame but still removes a critical Phe — distinguish from frameshift deletions which are not multiples of 3.'
  },
  inframe_del: {
    label:'In-frame deletion (-3)',
    apply: m => m.slice(0, 3) + m.slice(6),  // remove entire CCC codon
    effect:'<b>In-frame deletion.</b> 3 nucleotides removed → 1 amino acid lost (Pro), but reading frame preserved for downstream codons. Less severe than frameshift but can still abolish function if the deleted residue is critical. <b>ΔF508 in CFTR</b> (most common CF mutation) is exactly this: in-frame loss of Phe508.'
  },
  expansion: {
    label:'Trinucleotide expansion',
    apply: m => m.slice(0, 9) + 'AAA' + 'AAA' + 'AAA' + m.slice(9),  // expand AAA repeat
    effect:'<b>Trinucleotide repeat expansion.</b> Repeated codon motif grows larger across generations (genetic anticipation). Expanded repeats disrupt protein function or cause aggregation. Examples: <b>Huntington disease</b> (CAG/Gln repeats in HTT), <b>Fragile X syndrome</b> (CGG in FMR1), <b>myotonic dystrophy</b> (CTG in DMPK).'
  },
};

function mutApply(mutKey) {
  const m = MUTATIONS[mutKey];
  if (!m) return;
  const newMrna = m.apply(ORIG_MRNA);
  const newProtein = translateMrna(newMrna);
  const formatted = newMrna.match(/.{1,3}/g).join(' ');
  const origCodons = ORIG_MRNA.match(/.{1,3}/g);
  const newCodons = newMrna.match(/.{1,3}/g);
  // Highlight differences in red
  let highlighted = '';
  for (let i = 0; i < newCodons.length; i++) {
    const isDiff = !origCodons[i] || newCodons[i] !== origCodons[i];
    highlighted += isDiff
      ? `<span style="color:#C25B3F;background:rgba(194,91,63,0.15);padding:1px 4px;border-radius:3px">${newCodons[i]}</span> `
      : `${newCodons[i]} `;
  }
  document.getElementById('mutBox').innerHTML = `
    <div style="color:var(--ink-mute)">Mutated mRNA (5'→3')</div>
    <div style="font-weight:700;letter-spacing:0.18em;font-size:15px;color:#5FA874;margin:4px 0">5'-${highlighted.trim()}-3'</div>
    <div style="color:var(--ink-mute);margin-top:6px">Mutated protein</div>
    <div style="font-weight:700;letter-spacing:0.06em;font-size:14px;color:#1B3A2D;margin:4px 0">${newProtein}</div>
  `;
  document.getElementById('mutEffectInfo').innerHTML = m.effect;
  document.getElementById('mutStageTag').textContent = m.label;
  document.querySelectorAll('[data-mut]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.mut === mutKey);
  });
}

function initMutationSim() {
  if (!document.getElementById('mutBox')) return;
  document.querySelectorAll('[data-mut]').forEach(btn => {
    btn.addEventListener('click', () => mutApply(btn.dataset.mut));
  });
}

/* ---- CHI-SQUARE CALCULATOR ---- */
const CHI_TYPES = {
  mono:      { classes:['Dominant phenotype','Recessive phenotype'], ratio:[3, 1] },
  testcross: { classes:['Phenotype A','Phenotype B'], ratio:[1, 1] },
  dihybrid:  { classes:['A_B_','A_bb','aaB_','aabb'], ratio:[9, 3, 3, 1] },
  codom:     { classes:['Homo dom','Hetero','Homo rec'], ratio:[1, 2, 1] },
};
const CHI_CRITICAL = { 1: 3.84, 2: 5.99, 3: 7.81, 4: 9.49, 5: 11.07 };

function chiBuildRows(typeKey) {
  const t = CHI_TYPES[typeKey];
  if (!t) return;
  const tbody = document.getElementById('chiRows');
  tbody.innerHTML = '';
  t.classes.forEach((cls, i) => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td style="padding:8px;border:1px solid var(--line)">${cls}</td>
      <td style="padding:8px;border:1px solid var(--line)">${t.ratio[i]}</td>
      <td style="padding:8px;border:1px solid var(--line)"><input type="number" min="0" data-chi-row="${i}" style="width:80px;font-family:inherit;font-size:12px;padding:4px;border:1px solid var(--line);border-radius:4px" placeholder="0"></td>
      <td style="padding:8px;border:1px solid var(--line);color:var(--ink-mute)" data-chi-exp="${i}">—</td>
      <td style="padding:8px;border:1px solid var(--line);color:var(--ink-mute)" data-chi-term="${i}">—</td>
    `;
    tbody.appendChild(tr);
  });
  document.getElementById('chiResult').innerHTML = '';
}

function chiCompute() {
  const typeKey = document.getElementById('chiCrossType').value;
  const t = CHI_TYPES[typeKey];
  const observed = [];
  document.querySelectorAll('[data-chi-row]').forEach(input => {
    observed[parseInt(input.dataset.chiRow)] = parseFloat(input.value) || 0;
  });
  const total = observed.reduce((a, b) => a + b, 0);
  if (total === 0) {
    document.getElementById('chiResult').innerHTML = '<p style="color:#C25B3F;font-weight:700">Enter observed counts before computing.</p>';
    return;
  }
  const ratioSum = t.ratio.reduce((a, b) => a + b, 0);
  let chi2 = 0;
  observed.forEach((O, i) => {
    const E = total * t.ratio[i] / ratioSum;
    const term = Math.pow(O - E, 2) / E;
    chi2 += term;
    document.querySelector(`[data-chi-exp="${i}"]`).textContent = E.toFixed(2);
    document.querySelector(`[data-chi-term="${i}"]`).textContent = term.toFixed(3);
  });
  const df = t.classes.length - 1;
  const crit = CHI_CRITICAL[df];
  const reject = chi2 > crit;
  document.getElementById('chiResult').innerHTML = `
    <h5 style="margin:0 0 10px 0;font-family:'Playfair Display',serif">Result</h5>
    <p style="font-family:'JetBrains Mono',monospace;font-size:13px;margin:0 0 6px 0"><b>χ² = ${chi2.toFixed(3)}</b></p>
    <p style="font-family:'JetBrains Mono',monospace;font-size:12px;margin:0 0 6px 0;color:var(--ink-mute)">df = ${df} · critical value (α=0.05) = ${crit}</p>
    <p style="font-family:'Playfair Display',serif;font-size:14px;font-weight:700;margin:10px 0 0 0;color:${reject ? '#C25B3F' : '#5FA874'}">
      ${reject
        ? 'REJECT null hypothesis: observed counts do NOT fit the predicted ratio (data inconsistent with the cross model).'
        : 'FAIL TO REJECT null: observed counts are consistent with the predicted ratio (no significant deviation).'}
    </p>
    <p style="font-size:12px;color:var(--ink-mute);margin-top:8px;font-style:italic">${reject ? 'Possible explanations: linkage, lethality, segregation distortion, sampling error in small N, or wrong genetic model.' : 'Within sampling variation expected for the predicted Mendelian ratio.'}</p>
  `;
}

function initChiSquare() {
  if (!document.getElementById('chiTable')) return;
  const sel = document.getElementById('chiCrossType');
  sel.addEventListener('change', () => chiBuildRows(sel.value));
  document.getElementById('chiCompute').addEventListener('click', chiCompute);
  document.getElementById('chiClear').addEventListener('click', () => {
    chiBuildRows(sel.value);
  });
  chiBuildRows('mono');
}

