/* ---- DRIFT / BOTTLENECK / FOUNDER SIM ---- */
const DRIFT_STATE = { mode:'small', N:20, gens:80, p0:0.5, history:null };
function driftSimulate() {
  const N = DRIFT_STATE.N;
  const gens = DRIFT_STATE.gens;
  const trials = 8;
  const allLines = [];
  for (let t = 0; t < trials; t++) {
    let p = DRIFT_STATE.p0;
    if (DRIFT_STATE.mode === 'bottleneck' && t === 0) p = 0.5;
    if (DRIFT_STATE.mode === 'founder') p = 0.5;
    const line = [p];
    let curN = N;
    for (let g = 1; g < gens; g++) {
      if (DRIFT_STATE.mode === 'bottleneck' && g === 30) curN = 6; // bottleneck
      if (DRIFT_STATE.mode === 'bottleneck' && g === 35) curN = N; // recover
      // Sample 2*curN alleles binomially with success prob p
      let count = 0;
      for (let i = 0; i < 2 * curN; i++) if (Math.random() < p) count++;
      p = count / (2 * curN);
      line.push(p);
    }
    allLines.push(line);
  }
  DRIFT_STATE.history = allLines;
  driftRender();
}
function driftRender() {
  if (!DRIFT_STATE.history) return;
  const lines = DRIFT_STATE.history;
  const W = 820, H = 320;
  const yMin = 0, yMax = 1;
  const xPx = i => 40 + i * (W - 60) / (DRIFT_STATE.gens - 1);
  const yPx = p => 20 + (1 - p) * (H - 40);
  const colors = ['#5FA874','#C25B3F','#a378a5','#c19a3e','#3A2C7A','#5cabe6','#a06b3e','#7a2418'];
  let svg = `<svg viewBox="0 0 ${W} ${H + 40}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;background:#fff;border:1.5px solid #1B3A2D;border-radius:8px">
    <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="700" fill="#1B3A2D">ALLELE FREQUENCY OVER ${DRIFT_STATE.gens} GENERATIONS · N=${DRIFT_STATE.N}</text>
    <line x1="40" y1="${yPx(0)}" x2="${W-20}" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1"/>
    <line x1="40" y1="${yPx(1)}" x2="${W-20}" y2="${yPx(1)}" stroke="#1B3A2D" stroke-width="1"/>
    <text x="30" y="${yPx(1)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">1.0 (fixed)</text>
    <text x="30" y="${yPx(0.5)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">0.5</text>
    <text x="30" y="${yPx(0)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">0 (lost)</text>
    <line x1="40" y1="${yPx(0.5)}" x2="${W-20}" y2="${yPx(0.5)}" stroke="#1B3A2D" stroke-width="0.5" stroke-dasharray="3 3"/>`;
  if (DRIFT_STATE.mode === 'bottleneck') {
    const x1 = xPx(30), x2 = xPx(35);
    svg += `<rect x="${x1}" y="20" width="${x2-x1}" height="${H-40}" fill="rgba(194,91,63,0.15)"/>
      <text x="${(x1+x2)/2}" y="14" text-anchor="middle" font-size="9" font-weight="700" fill="#C25B3F">bottleneck</text>`;
  }
  lines.forEach((line, i) => {
    const pts = line.map((p, g) => `${xPx(g)},${yPx(p)}`).join(' ');
    svg += `<polyline points="${pts}" fill="none" stroke="${colors[i % colors.length]}" stroke-width="2"/>`;
  });
  svg += `</svg>`;
  document.getElementById('driftBody').innerHTML = svg + `
    <div style="margin-top:14px;background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:14px">
      <p style="font-size:13px;line-height:1.6;color:#1B3A2D;margin:0">
        <b>Genetic drift</b> = random changes in allele frequencies due to sampling. Stronger in small populations.<br>
        <b>Bottleneck</b> = sharp temporary reduction in population size (disaster, hunting) → loss of genetic diversity. Cheetahs ~10,000 years ago.<br>
        <b>Founder effect</b> = small subset of population establishes a new population → starting allele frequencies are not representative. Amish, Ashkenazi Jewish populations carry concentrated alleles for various conditions.
      </p>
    </div>
  `;
}
function initDriftSim() {
  if (!document.getElementById('driftBody')) return;
  document.querySelectorAll('[data-drift]').forEach(b => b.addEventListener('click', () => {
    const m = b.dataset.drift;
    DRIFT_STATE.mode = m;
    if (m === 'small') DRIFT_STATE.N = 20;
    else if (m === 'large') DRIFT_STATE.N = 2000;
    else if (m === 'bottleneck') DRIFT_STATE.N = 100;
    else if (m === 'founder') DRIFT_STATE.N = 10;
    DRIFT_STATE.gens = 80;
    DRIFT_STATE.p0 = (m === 'founder') ? Math.random() * 0.6 + 0.2 : 0.5;
    document.querySelectorAll('[data-drift]').forEach(bb => bb.classList.toggle('active', bb.dataset.drift === m));
    driftSimulate();
  }));
  document.getElementById('driftPlay').addEventListener('click', () => driftSimulate());
  document.getElementById('driftReset').addEventListener('click', () => {
    DRIFT_STATE.mode = 'small'; DRIFT_STATE.N = 20; DRIFT_STATE.gens = 80; DRIFT_STATE.p0 = 0.5;
    document.querySelectorAll('[data-drift]').forEach(b => b.classList.toggle('active', b.dataset.drift === 'small'));
    driftSimulate();
  });
  driftSimulate();
}

