/* ---- BIOGEOCHEMICAL CYCLES ---- */
const BGC_DATA = {
  carbon: {
    label:'Carbon cycle',
    info:'<b>Carbon</b>: backbone of organic molecules.<br><b>Reservoirs:</b> atmosphere (CO₂), ocean (dissolved + carbonates), biosphere (organic), lithosphere (fossil fuels, limestone).<br><br><b>Fluxes:</b><br>• <b>Photosynthesis</b>: CO₂ → glucose (atmosphere → biosphere)<br>• <b>Respiration / decomposition</b>: organic → CO₂<br>• <b>Combustion</b>: fossil fuels → CO₂ (anthropogenic, the issue)<br>• <b>Ocean exchange</b>: CO₂ ↔ HCO₃⁻ + H₂CO₃ (ocean acidification when too much CO₂ enters)<br>• <b>Carbonate weathering / sedimentation</b>: long-term sink<br><br><b>Climate impact:</b> CO₂ traps IR → greenhouse warming. Pre-industrial ~280 ppm → today ~420 ppm.',
  },
  nitrogen: {
    label:'Nitrogen cycle',
    info:'<b>Nitrogen</b>: in amino acids, nucleic acids. ~78% of atmosphere as N₂ but inaccessible to most organisms.<br><br><b>Steps:</b><br>1. <b>Nitrogen fixation</b>: N₂ → NH₃. Done by bacteria (Rhizobium, cyanobacteria) and lightning. Industrial Haber process.<br>2. <b>Nitrification</b>: NH₃ → NO₂⁻ → NO₃⁻. Soil bacteria (Nitrosomonas, Nitrobacter).<br>3. <b>Assimilation</b>: plants take up NO₃⁻ or NH₄⁺ → make amino acids.<br>4. <b>Ammonification</b>: dead organisms + waste → NH₃ (decomposers).<br>5. <b>Denitrification</b>: NO₃⁻ → N₂ (anaerobic bacteria, returns N to atmosphere).<br><br><b>Fertilizer pollution:</b> excess NO₃⁻ in waterways → algal blooms → eutrophication → dead zones (Gulf of Mexico).',
  },
  phosphorus: {
    label:'Phosphorus cycle',
    info:'<b>Phosphorus</b>: in DNA/RNA backbone, ATP, phospholipids, bones (hydroxyapatite).<br><br><b>NO atmospheric phase</b> (unlike C, N, S, water). Cycles through rocks, soil, water, organisms.<br><br><b>Steps:</b><br>• Weathering of phosphate-containing rocks → PO₄³⁻ in soil/water<br>• Plants take up PO₄³⁻ → into organic molecules<br>• Animals eat plants/other animals → get P<br>• Decomposers return P to soil<br>• Sedimentation in oceans → eventually back to rock (very slow, geological time)<br><br><b>Limiting nutrient</b> in many ecosystems (especially aquatic). Mining for fertilizer is a non-renewable resource concern.',
  },
  water: {
    label:'Water cycle (hydrologic)',
    info:'<b>Water cycle</b> — driven by solar energy + gravity.<br><br><b>Processes:</b><br>• <b>Evaporation</b>: liquid → vapor (oceans = 86% of evaporation)<br>• <b>Transpiration</b>: water from plant leaves<br>• <b>Condensation</b>: vapor → cloud droplets<br>• <b>Precipitation</b>: rain, snow, sleet, hail<br>• <b>Runoff</b>: surface flow back to oceans<br>• <b>Infiltration</b>: groundwater (aquifers — long-term storage)<br><br><b>Reservoirs:</b> oceans (97%), ice caps (2%), groundwater + lakes/rivers (1%).<br><b>Anthropogenic impacts:</b> irrigation, deforestation (less transpiration → drier regions), urbanization (more runoff, less infiltration), groundwater depletion.',
  },
  sulfur: {
    label:'Sulfur cycle',
    info:'<b>Sulfur</b>: in amino acids cysteine + methionine; disulfide bridges in proteins; in coenzyme A.<br><br><b>Sources:</b> rock weathering, volcanic emissions (SO₂, H₂S), decomposition of organisms, industrial emissions.<br><br><b>Microbial steps:</b><br>• <b>Sulfur reducers</b> (anaerobic, e.g., Desulfovibrio): SO₄²⁻ → H₂S<br>• <b>Sulfur oxidizers</b> (aerobic): H₂S → S → SO₄²⁻ (chemolithotrophs at hydrothermal vents)<br>• <b>Plants/animals</b>: assimilate SO₄²⁻ → S-amino acids<br><br><b>Acid rain:</b> SO₂ from coal burning → H₂SO₄ in atmosphere → acidifies lakes, damages forests, dissolves limestone.',
  },
};
function cycleSetMode(mode) {
  const d = BGC_DATA[mode];
  if (!d) return;
  document.getElementById('cyclesBody').innerHTML = `
    <div style="background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:24px;min-height:420px">
      <h4 style="margin:0 0 14px 0;font-family:'Playfair Display',serif;font-size:20px;color:#1B3A2D">${d.label}</h4>
      <div style="font-size:14px;line-height:1.7;color:#1B3A2D">${d.info}</div>
    </div>
  `;
  document.getElementById('cyclesStageTag').textContent = d.label;
  document.querySelectorAll('[data-cycle]').forEach(b => b.classList.toggle('active', b.dataset.cycle === mode));
}
function initBiogeochemicalCycles() {
  if (!document.getElementById('cyclesBody')) return;
  document.querySelectorAll('[data-cycle]').forEach(b => b.addEventListener('click', () => cycleSetMode(b.dataset.cycle)));
  cycleSetMode('carbon');
}

