/* ---- POPULATION GROWTH ---- */
function popgrowRender() {
  const r = parseFloat(document.getElementById('popRSlider').value);
  const K = parseFloat(document.getElementById('popKSlider').value);
  document.getElementById('popR').textContent = r.toFixed(2);
  document.getElementById('popK').textContent = K;
  const N0 = 10, T = 50, dt = 0.5;
  const expo = []; let nE = N0;
  const log = []; let nL = N0;
  for (let t = 0; t <= T; t += dt) {
    expo.push({ t, n: nE });
    log.push({ t, n: nL });
    nE += r * nE * dt;
    nL += r * nL * (1 - nL / K) * dt;
  }
  const W = 760, H = 320;
  const yMax = Math.max(K * 1.2, ...expo.slice(0, 30).map(p => p.n));
  const yMin = 0;
  const xPx = t => 50 + t * (W - 70) / T;
  const yPx = n => 20 + (1 - (n - yMin) / (yMax - yMin)) * (H - 40);
  let svg = `<svg viewBox="0 0 ${W} ${H + 40}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;background:#fff;border:1.5px solid #1B3A2D;border-radius:8px">
    <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="700" fill="#1B3A2D">EXPONENTIAL vs LOGISTIC GROWTH</text>
    <line x1="50" y1="${yPx(0)}" x2="${W-20}" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1"/>
    <line x1="50" y1="20" x2="50" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1"/>
    <line x1="50" y1="${yPx(K)}" x2="${W-20}" y2="${yPx(K)}" stroke="#a378a5" stroke-width="1.5" stroke-dasharray="4 3"/>
    <text x="${W-25}" y="${yPx(K)-4}" text-anchor="end" font-size="9" font-weight="700" fill="#a378a5">K = ${K}</text>
    <polyline points="${expo.filter(p => p.n < yMax).map(p => xPx(p.t)+','+yPx(p.n)).join(' ')}" stroke="#C25B3F" stroke-width="2.5" fill="none"/>
    <polyline points="${log.map(p => xPx(p.t)+','+yPx(p.n)).join(' ')}" stroke="#5FA874" stroke-width="2.5" fill="none"/>
    <text x="${W-25}" y="40" text-anchor="end" font-size="10" font-weight="700" fill="#C25B3F">exponential: dN/dt = rN</text>
    <text x="${W-25}" y="58" text-anchor="end" font-size="10" font-weight="700" fill="#5FA874">logistic: dN/dt = rN(1−N/K)</text>
    <text x="${W/2}" y="${H+25}" text-anchor="middle" font-size="10" fill="#1B3A2D">time →</text>
    <text x="20" y="${(yPx(0)+20)/2}" text-anchor="middle" font-size="10" fill="#1B3A2D" transform="rotate(-90, 20, ${(yPx(0)+20)/2})">population N</text>
  </svg>`;
  document.getElementById('popgrowBody').innerHTML = svg;
}
function initPopGrowth() {
  if (!document.getElementById('popgrowBody')) return;
  document.getElementById('popRSlider').addEventListener('input', popgrowRender);
  document.getElementById('popKSlider').addEventListener('input', popgrowRender);
  popgrowRender();
}

/* ---- SURVIVORSHIP CURVES ---- */
function initSurvivorship() {
  if (!document.getElementById('survBody')) return;
  const W = 800, H = 380;
  const xPx = a => 60 + a * (W - 80) / 100;
  const yPx = lp => 30 + (3 - lp) * (H - 60) / 3;
  const typeI = []; for (let a = 0; a <= 100; a++) typeI.push({ a, lp: 3 - 0.0006 * Math.pow(a, 2.5) / 10 });
  const typeII = []; for (let a = 0; a <= 100; a++) typeII.push({ a, lp: 3 - 0.03 * a });
  const typeIII = []; for (let a = 0; a <= 100; a++) typeIII.push({ a, lp: 3 - 1.5 * Math.log10(1 + a / 1.5) });
  const ptsI = typeI.map(p => `${xPx(p.a)},${yPx(Math.max(0, p.lp))}`).join(' ');
  const ptsII = typeII.map(p => `${xPx(p.a)},${yPx(Math.max(0, p.lp))}`).join(' ');
  const ptsIII = typeIII.map(p => `${xPx(p.a)},${yPx(Math.max(0, p.lp))}`).join(' ');
  document.getElementById('survBody').innerHTML = `
    <svg viewBox="0 0 ${W} ${H + 100}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;background:linear-gradient(180deg,#fbf6e9 0%,#f0e9d6 100%);border-radius:10px">
      <text x="${W/2}" y="22" text-anchor="middle" font-size="14" font-weight="700" letter-spacing="0.14em" fill="#1B3A2D">SURVIVORSHIP CURVES — Type I, II, III</text>
      <line x1="60" y1="${yPx(0)}" x2="${W-20}" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1.5"/>
      <line x1="60" y1="${yPx(3)}" x2="60" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1.5"/>
      <text x="55" y="${yPx(3)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">1000</text>
      <text x="55" y="${yPx(2)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">100</text>
      <text x="55" y="${yPx(1)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">10</text>
      <text x="55" y="${yPx(0)+4}" text-anchor="end" font-size="9" fill="#1B3A2D">1</text>
      <text x="30" y="${(yPx(3)+yPx(0))/2}" text-anchor="middle" font-size="10" fill="#1B3A2D" transform="rotate(-90, 30, ${(yPx(3)+yPx(0))/2})">log(survivors)</text>
      <text x="${W/2}" y="${H+20}" text-anchor="middle" font-size="10" fill="#1B3A2D">% lifespan</text>
      <polyline points="${ptsI}" stroke="#5FA874" stroke-width="3" fill="none"/>
      <polyline points="${ptsII}" stroke="#a378a5" stroke-width="3" fill="none"/>
      <polyline points="${ptsIII}" stroke="#C25B3F" stroke-width="3" fill="none"/>
      <text x="${W-25}" y="60" text-anchor="end" font-size="11" font-weight="700" fill="#5FA874">Type I — humans, large mammals</text>
      <text x="${W-25}" y="78" text-anchor="end" font-size="11" font-weight="700" fill="#a378a5">Type II — birds, small mammals, reptiles</text>
      <text x="${W-25}" y="96" text-anchor="end" font-size="11" font-weight="700" fill="#C25B3F">Type III — fish, oysters, plants</text>
      <text x="60" y="${H+50}" font-size="11" font-weight="700" fill="#1B3A2D">Type I (concave): low juvenile mortality, most die in old age (parental care, K-selected).</text>
      <text x="60" y="${H+68}" font-size="11" font-weight="700" fill="#1B3A2D">Type II (linear): roughly constant per-capita death rate at any age (birds, hydra).</text>
      <text x="60" y="${H+86}" font-size="11" font-weight="700" fill="#1B3A2D">Type III (convex): high juvenile mortality, few survivors live long (r-selected — many offspring, low investment).</text>
    </svg>
  `;
}

/* ---- PREDATOR-PREY (LOTKA-VOLTERRA) ---- */
const PP_STATE = { animId:null, t:0, lastFrame:0, playing:false, R:50, P:9, hist:[] };
function ppStep() {
  // Lotka-Volterra: dR/dt = aR - bRP; dP/dt = cRP - dP
  const a = 0.6, b = 0.04, c = 0.025, d = 0.5;
  const dt = 0.05;
  let R = PP_STATE.R, P = PP_STATE.P;
  for (let i = 0; i < 4; i++) {
    const dR = (a * R - b * R * P) * dt;
    const dP = (c * R * P - d * P) * dt;
    R += dR; P += dP;
    if (R < 0.5) R = 0.5;
    if (P < 0.5) P = 0.5;
  }
  PP_STATE.R = R; PP_STATE.P = P;
  PP_STATE.t += 0.2;
  PP_STATE.hist.push({ t: PP_STATE.t, R, P });
  if (PP_STATE.hist.length > 600) PP_STATE.hist.shift();
}
function ppRender() {
  const W = 820, H = 360;
  const allR = PP_STATE.hist.map(p => p.R);
  const allP = PP_STATE.hist.map(p => p.P);
  const yMax = Math.max(50, ...allR, ...allP) * 1.1;
  const tMin = PP_STATE.hist[0]?.t || 0;
  const tMax = PP_STATE.hist[PP_STATE.hist.length - 1]?.t || 1;
  const xPx = t => 50 + (t - tMin) / Math.max(1, tMax - tMin) * (W - 70);
  const yPx = n => 30 + (1 - n / yMax) * (H - 60);
  const ptsR = PP_STATE.hist.map(p => `${xPx(p.t)},${yPx(p.R)}`).join(' ');
  const ptsP = PP_STATE.hist.map(p => `${xPx(p.t)},${yPx(p.P)}`).join(' ');
  document.getElementById('ppBody').innerHTML = `
    <svg viewBox="0 0 ${W} ${H + 40}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;background:linear-gradient(180deg,#fbf6e9 0%,#f0e9d6 100%);border-radius:10px">
      <text x="${W/2}" y="20" text-anchor="middle" font-size="13" font-weight="700" letter-spacing="0.14em" fill="#1B3A2D">LOTKA-VOLTERRA — predator/prey oscillation</text>
      <line x1="50" y1="${yPx(0)}" x2="${W-20}" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1"/>
      <line x1="50" y1="30" x2="50" y2="${yPx(0)}" stroke="#1B3A2D" stroke-width="1"/>
      <polyline points="${ptsR}" stroke="#5FA874" stroke-width="2" fill="none"/>
      <polyline points="${ptsP}" stroke="#C25B3F" stroke-width="2" fill="none"/>
      <text x="${W-25}" y="50" text-anchor="end" font-size="11" font-weight="700" fill="#5FA874">prey (rabbits)</text>
      <text x="${W-25}" y="68" text-anchor="end" font-size="11" font-weight="700" fill="#C25B3F">predator (foxes)</text>
      <text x="${W/2}" y="${H+25}" text-anchor="middle" font-size="10" fill="#1B3A2D">time →</text>
    </svg>
    <div style="margin-top:14px;background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:14px">
      <p style="font-size:13px;line-height:1.6;color:#1B3A2D;margin:0">
        <b>Lotka-Volterra equations:</b><br>
        <span style="font-family:monospace">dR/dt = aR − bRP</span> &nbsp;(prey grow, eaten by predators)<br>
        <span style="font-family:monospace">dP/dt = cRP − dP</span> &nbsp;(predators grow with prey, die at constant rate)<br><br>
        <b>Predator peak lags prey peak</b> by ~¼ cycle. Real-world example: lynx + snowshoe hare data from Hudson Bay Company furs (~10-yr cycles).
      </p>
    </div>
  `;
}
function ppTick() {
  if (!PP_STATE.playing) return;
  ppStep();
  ppRender();
  PP_STATE.animId = requestAnimationFrame(ppTick);
}
function initPredatorPrey() {
  if (!document.getElementById('ppBody')) return;
  // Seed with initial run
  for (let i = 0; i < 100; i++) ppStep();
  ppRender();
  document.getElementById('ppPlay').addEventListener('click', () => {
    PP_STATE.playing = true;
    PP_STATE.animId = requestAnimationFrame(ppTick);
  });
  document.getElementById('ppReset').addEventListener('click', () => {
    PP_STATE.playing = false;
    cancelAnimationFrame(PP_STATE.animId);
    PP_STATE.t = 0; PP_STATE.R = 50; PP_STATE.P = 9; PP_STATE.hist = [];
    for (let i = 0; i < 100; i++) ppStep();
    ppRender();
  });
}

/* ---- SYMBIOSIS ---- */
function initSymbiosis() {
  if (!document.getElementById('symbBody')) return;
  document.getElementById('symbBody').innerHTML = `
    <svg viewBox="0 0 900 360" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;background:linear-gradient(180deg,#fbf6e9 0%,#f0e9d6 100%);border-radius:10px">
      <text x="450" y="30" text-anchor="middle" font-size="14" font-weight="700" letter-spacing="0.16em" fill="#1B3A2D">SPECIES INTERACTIONS</text>
      <foreignObject x="40" y="60" width="820" height="280">
        <table xmlns="http://www.w3.org/1999/xhtml" style="width:100%;border-collapse:collapse;font-family:JetBrains Mono,monospace;font-size:11.5px;background:#fff;border:1.5px solid #1B3A2D">
          <thead style="background:rgba(13,32,24,0.08)">
            <tr><th style="padding:8px;border:1px solid #1B3A2D">Type</th><th style="padding:8px;border:1px solid #1B3A2D;text-align:center">Sp 1</th><th style="padding:8px;border:1px solid #1B3A2D;text-align:center">Sp 2</th><th style="padding:8px;border:1px solid #1B3A2D">Examples</th></tr>
          </thead>
          <tbody>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Mutualism</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#5FA874;font-weight:700">+</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#5FA874;font-weight:700">+</td><td style="padding:5px;border:1px solid #1B3A2D">Mycorrhizae, lichen, gut microbes, pollination, clownfish + anemone, oxpecker + zebra</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Commensalism</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#5FA874;font-weight:700">+</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center">0</td><td style="padding:5px;border:1px solid #1B3A2D">Barnacles on whales, cattle egrets feeding on insects flushed by livestock, epiphytes on trees</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Parasitism</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#5FA874;font-weight:700">+</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#C25B3F;font-weight:700">−</td><td style="padding:5px;border:1px solid #1B3A2D">Tapeworm, fleas, ticks, plasmodium (malaria), brood parasitism (cuckoos)</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Predation</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#5FA874;font-weight:700">+</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#C25B3F;font-weight:700">−</td><td style="padding:5px;border:1px solid #1B3A2D">Lion + zebra, wolf + deer, mantis + insect (lethal interaction)</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Herbivory</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#5FA874;font-weight:700">+</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#C25B3F;font-weight:700">−</td><td style="padding:5px;border:1px solid #1B3A2D">Caterpillar + leaf, deer + plant (usually doesn\'t kill)</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Competition</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#C25B3F;font-weight:700">−</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#C25B3F;font-weight:700">−</td><td style="padding:5px;border:1px solid #1B3A2D">Two predator species after same prey; weed species in same plot</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Amensalism</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center">0</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center;color:#C25B3F;font-weight:700">−</td><td style="padding:5px;border:1px solid #1B3A2D">Penicillium kills bacteria (penicillin) but bacteria don\'t affect Penicillium</td></tr>
            <tr><td style="padding:5px;border:1px solid #1B3A2D;font-weight:700">Neutralism</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center">0</td><td style="padding:5px;border:1px solid #1B3A2D;text-align:center">0</td><td style="padding:5px;border:1px solid #1B3A2D">Two species in same area that don\'t interact</td></tr>
          </tbody>
        </table>
      </foreignObject>
    </svg>
    <div style="margin-top:14px;background:rgba(95,168,116,0.08);border-left:4px solid #5FA874;padding:12px 16px;border-radius:6px">
      <p style="font-size:13px;color:#1B3A2D;margin:0"><b>Competitive exclusion principle (Gause):</b> two species with identical niches cannot coexist indefinitely — one will outcompete the other. Real species coexist by occupying slightly different niches (resource partitioning).</p>
    </div>
  `;
}

/* ---- CONDITIONING TRAINER ---- */
const COND_QUIZ = [
  { q:'A dog learns to ignore a constantly-running fan and stops reacting to it.', a:'habituation', alt:['classical conditioning','operant conditioning','imprinting'] },
  { q:'Pavlov\'s dogs salivate when they hear a bell that has been paired with food.', a:'classical conditioning', alt:['operant conditioning','habituation','sensitization'] },
  { q:'A rat presses a lever and receives food; it presses more often.', a:'operant conditioning (positive reinforcement)', alt:['classical conditioning','negative reinforcement','punishment'] },
  { q:'A baby duck follows the first moving thing it sees during its critical period.', a:'imprinting', alt:['habituation','classical conditioning','operant conditioning'] },
  { q:'A cat learns to escape a shock by pressing a button — does it more in the future to avoid the shock.', a:'negative reinforcement', alt:['punishment','habituation','classical conditioning'] },
  { q:'A child receives a time-out for hitting another kid; hitting decreases.', a:'punishment', alt:['negative reinforcement','operant conditioning (positive)','habituation'] },
  { q:'A fish only sees other fish from a young age — never learns to recognize its mother.', a:'imprinting failure', alt:['habituation','classical conditioning','sensitization'] },
  { q:'After a single loud noise, a person becomes much MORE jumpy with subsequent stimuli.', a:'sensitization', alt:['habituation','classical conditioning','imprinting'] },
];
let condIdx = 0;
function condRender() {
  const item = COND_QUIZ[condIdx];
  const opts = [item.a, ...item.alt].sort(() => Math.random() - 0.5);
  document.getElementById('condBody').innerHTML = `
    <div style="background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:24px;min-height:380px">
      <h4 style="margin:0 0 8px 0;font-family:'Playfair Display',serif;font-size:18px;color:#1B3A2D">Scenario ${condIdx + 1} of ${COND_QUIZ.length}</h4>
      <p style="font-size:15px;line-height:1.5;color:#1B3A2D;margin:14px 0 22px 0">${item.q}</p>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${opts.map(o => `<button class="cond-opt" data-cond-ans="${o}" style="font-family:'JetBrains Mono',monospace;font-size:13px;padding:10px 14px;text-align:left;background:#fff;border:1.5px solid var(--line);border-radius:6px;cursor:pointer">${o}</button>`).join('')}
      </div>
      <div id="condFeedback" style="margin-top:18px;font-size:14px;font-weight:700"></div>
    </div>
  `;
  document.querySelectorAll('.cond-opt').forEach(btn => btn.addEventListener('click', () => {
    const correct = btn.dataset.condAns === item.a;
    document.getElementById('condFeedback').innerHTML = correct
      ? `<span style="color:#5FA874">Correct — ${item.a}.</span> &nbsp; <button id="condNext" style="margin-left:8px;font-family:inherit;font-size:13px;padding:8px 14px;background:#c19a3e;border:1px solid #1B3A2D;color:#0d2018;border-radius:6px;cursor:pointer;font-weight:700">Next</button>`
      : `<span style="color:#C25B3F">Not quite — the correct answer is <b>${item.a}</b>.</span> &nbsp; <button id="condNext" style="margin-left:8px;font-family:inherit;font-size:13px;padding:8px 14px;background:#c19a3e;border:1px solid #1B3A2D;color:#0d2018;border-radius:6px;cursor:pointer;font-weight:700">Next</button>`;
    document.getElementById('condStageTag').textContent = correct ? 'Correct' : 'Try the next one';
    document.getElementById('condNext').addEventListener('click', () => {
      condIdx = (condIdx + 1) % COND_QUIZ.length;
      condRender();
    });
  }));
}
function initConditioningTrainer() {
  if (!document.getElementById('condBody')) return;
  condRender();
}

/* ---- HW WORD PROBLEMS ---- */
const HW_WORDS = [
  { q:'In a population, the recessive disorder PKU has a frequency of 1/10,000 (q² = 0.0001). What is the carrier frequency (Aa)?', steps:'q² = 0.0001 → q = 0.01. p = 1 − q = 0.99. Carrier frequency 2pq = 2 × 0.99 × 0.01 = 0.0198 ≈ 1.98%.', a:'~1.98% (1 in 50)' },
  { q:'In an HW population, 16% are homozygous recessive (aa). What % are heterozygous (Aa)?', steps:'q² = 0.16 → q = 0.4. p = 0.6. 2pq = 2 × 0.6 × 0.4 = 0.48 = 48%.', a:'48%' },
  { q:'9% of population shows the recessive trait. If 100 individuals, how many carriers expected?', steps:'q² = 0.09 → q = 0.3. p = 0.7. 2pq = 2 × 0.7 × 0.3 = 0.42. 100 × 0.42 = 42 carriers.', a:'42 carriers' },
  { q:'In a sample of 1000, allele A is observed at frequency 0.7. How many heterozygous individuals are expected?', steps:'p = 0.7, q = 0.3. 2pq = 2 × 0.7 × 0.3 = 0.42. 1000 × 0.42 = 420.', a:'420 individuals' },
  { q:'For sickle cell (recessive), 1/400 newborns affected in a population. What is the allele frequency q?', steps:'q² = 1/400 = 0.0025 → q = √0.0025 = 0.05.', a:'q = 0.05' },
];
let hwIdx = 0;
function hwwRenderWordPanel() {
  const wp = document.getElementById('hwwWordPanel');
  if (!wp) return;
  const item = HW_WORDS[hwIdx];
  wp.innerHTML = `
    <div style="background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:18px">
      <h4 style="margin:0 0 8px 0;font-family:'Playfair Display',serif;font-size:16px;color:#1B3A2D">DAT-style word problem ${hwIdx + 1} of ${HW_WORDS.length}</h4>
      <p style="font-size:13px;line-height:1.6;color:#1B3A2D;margin:10px 0 14px 0">${item.q}</p>
      <button id="hwwShow" style="font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;padding:6px 14px;background:#c19a3e;border:1px solid #1B3A2D;color:#0d2018;border-radius:6px;cursor:pointer">Show solution</button>
      <button id="hwwNext" style="font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;padding:6px 14px;background:#fff;border:1px solid var(--line);color:#1B3A2D;border-radius:6px;cursor:pointer;margin-left:8px">Next problem</button>
      <div id="hwwSol" style="margin-top:14px;display:none;background:rgba(95,168,116,0.08);border-left:4px solid #5FA874;padding:12px;border-radius:6px">
        <p style="font-size:12px;line-height:1.6;color:#1B3A2D;margin:0"><b>Steps:</b> ${item.steps}</p>
        <p style="font-size:13px;font-weight:700;color:#5FA874;margin:8px 0 0 0">Answer: ${item.a}</p>
      </div>
    </div>
  `;
  document.getElementById('hwwShow').addEventListener('click', () => {
    document.getElementById('hwwSol').style.display = 'block';
  });
  document.getElementById('hwwNext').addEventListener('click', () => {
    hwIdx = (hwIdx + 1) % HW_WORDS.length;
    hwwRenderWordPanel();
  });
}
function initHwWordTrainer() {
  // No-op: rendering is handled by initHwBubbleCloud, which mounts the
  // bubble simulator on top and calls hwwRenderWordPanel for the problems below.
}

/* ============================================================
   COACH MODE — floating helper that explains current context
   ============================================================ */
const COACH_TIPS = {
  // Cell Lab
  atlas: { title:'Cell Atlas', body:'<p>Click any organelle to learn its structure + function. The DAT loves "which organelle does X?" questions — endomembrane system, mitochondria/chloroplast endosymbiosis, and lysosomes are common targets.</p><p><b>Focus most on:</b> ER (rough vs smooth), Golgi (modification + sorting), mitochondrion (ETC + matrix vs intermembrane space), nucleus (transcription compartment).</p>' },
  energy: { title:'Bioenergetics', body:'<p>Drag enzymes to their pathway slots. Glycolysis → pyruvate oxidation → Krebs → ETC + chemiosmosis. Track ATP per glucose: 2 (glyc) + 0 (PDH) + 2 (Krebs) + 28 (ETC) ≈ 32 ATP eukaryotic.</p><p><b>Three things the DAT tests obsessively:</b> location of each step, NADH/FADH₂ yields, reactants/products of each substep.</p>' },
  bench: { title:'Lab Bench', body:'<p>Practice gel electrophoresis, PCR cycling, and microscopy techniques. Every DAT bio test asks at least one molecular technique question.</p>' },
  kinetics: { title:'Enzyme Kinetics', body:'<p>Slide [S] and inhibitors to see how Vmax and Km respond. Memorize: <b>competitive</b> = Vmax same, Km up. <b>Non-competitive</b> = Vmax down, Km same. <b>Uncompetitive</b> = both decrease.</p>' },
  cycle: { title:'Cell Cycle', body:'<p>Click each phase to see what happens + which cyclin-CDK pair drives it. Critical checkpoints: G1/S (Rb-E2F), G2/M (cyclin B-CDK1 = MPF), spindle (cohesin/separase).</p>' },
  fork: { title:'DNA Replication Fork', body:'<p>Press play to see all 5 enzymes working in concert. <b>Why fragments on lagging?</b> DNA polymerase only synthesizes 5\'→3\'. Lagging template runs the wrong way relative to fork → must work in pieces.</p>' },
  tx: { title:'Transcription/Translation', body:'<p>Watch the central dogma in motion. <b>Common DAT trap:</b> RNA Pol II reads template 3\'→5\', synthesizes mRNA 5\'→3\'. Ribosome reads mRNA 5\'→3\'. tRNA brings amino acid for codon at A site → peptide bond → translocation.</p>' },
  mem: { title:'Membrane Transport', body:'<p>Pick each mode to see what crosses + at what energy cost. <b>Passive</b>: simple diffusion, osmosis, facilitated. <b>Active</b>: primary (ATP direct), secondary (uses gradient set up by primary).</p>' },
  sig: { title:'Signal Transduction', body:'<p>Pick a receptor type. <b>GPCR</b>: ligand → GPCR → G-protein → effector → 2nd messenger. <b>RTK</b>: ligand → dimerize → autophosphorylate → MAPK cascade. <b>Steroid</b>: lipid-soluble → enters cell → nuclear receptor.</p>' },
  exp: { title:'Classic Experiments', body:'<p>"Which experiment showed X?" is a frequent DAT question. Memorize: <b>Griffith</b> → transformation. <b>Avery</b> → DNA is the molecule. <b>Hershey-Chase</b> → confirmed DNA. <b>Meselson-Stahl</b> → semiconservative replication.</p>' },
  tech: { title:'Lab Tech Library', body:'<p>Mnemonic <b>SNoW DRoP</b>: Southern → DNA, Northern → RNA, Western → Protein. ELISA = antibody-based assay. Sanger = chain-termination sequencing. CRISPR-Cas9 = programmable cutting.</p>' },
  cmp: { title:'Pro vs Eu', body:'<p>Most testable diff: <b>nucleus + membrane organelles + 80S ribosomes + linear chromatin in eukaryotes</b>. Prokaryotes: nucleoid, no organelles, 70S, circular DNA + plasmids, peptidoglycan wall.</p>' },
  prot: { title:'Protein Structure', body:'<p>Four levels: <b>1°</b> (peptide bonds, sequence) → <b>2°</b> (H-bonds in backbone, α-helix/β-sheet) → <b>3°</b> (full 3D fold, dominated by hydrophobic effect + disulfides) → <b>4°</b> (multiple subunits, like hemoglobin).</p>' },
  // Genetics
  punnett: { title:'Punnett Solver', body:'<p>Type any cross. The Punnett square is just a multiplication table for gametes. <b>Test cross</b> = with homozygous recessive — reveals genotype of unknown.</p>' },
  pedigree: { title:'Pedigree Analyzer', body:'<p>Decision tree:</p><ol><li>Both sexes affected? → autosomal. Only males? → X-linked recessive likely.</li><li>Skips generations? → recessive. Every gen? → dominant.</li></ol>' },
  hw: { title:'Hardy-Weinberg', body:'<p>p + q = 1 and p² + 2pq + q² = 1. <b>Most common DAT setup:</b> "X% are affected (recessive)" → q² = X. From q, find p, then carriers (2pq).</p>' },
  inheritree: { title:'Inheritance Tree', body:'<p>Pick an inheritance pattern + founder genotypes. Click any individual to see their possible genotypes + probabilities given parents. The tree visualizes how alleles propagate across 4 generations.</p>' },
  mut: { title:'Mutation Sim', body:'<p>Click each mutation type to see effect on protein. <b>Most disruptive:</b> nonsense > frameshift >> missense > silent. Frameshift insertions/deletions of multiples of 3 are in-frame (less severe).</p>' },
  chi: { title:'Chi-square', body:'<p>χ² = Σ(O−E)²/E. df = (# classes) − 1. Compare χ² to critical value at α=0.05. <b>If χ² &gt; critical → reject null</b> (data don\'t fit predicted ratio).</p>' },
  epi: { title:'Epistasis', body:'<p>Variations on 9:3:3:1. <b>Memorize:</b> 9:3:4 (recessive epistasis), 12:3:1 (dominant), 15:1 (duplicate dominant), 9:7 (complementary), 13:3 (dominant + recessive).</p>' },
  reg: { title:'Gene Regulation', body:'<p>Eukaryotic regulation happens at every level: chromatin (histone acetylation, DNA methylation), transcription (TFs, enhancers), splicing, mRNA stability, translation, post-translational.</p>' },
  // Body Systems
  bodymap: { title:'Body Map', body:'<p>Click any organ to see its system + function. The DAT tests organ system integration heavily — cardio + pulmonary + renal share a lot of physiology.</p>' },
  cardiac: { title:'Cardiac Cycle', body:'<p>Press play to see the heart pump. <b>S1</b> = AV valves close (start of systole). <b>S2</b> = semilunar valves close (end of systole). EKG: P (atrial depol), QRS (vent depol), T (vent repol).</p>' },
  bohr: { title:'Bohr Curve', body:'<p>Sigmoidal Hb-O₂ curve. <b>Right shift</b> (release O₂) caused by: ↑CO₂, ↑H⁺ (low pH), ↑temp, ↑BPG. Tissue conditions. <b>Left shift</b> (hold O₂): opposite. Fetal Hb is left of adult.</p>' },
  nephron: { title:'Nephron', body:'<p>Filtration → reabsorption → secretion. <b>PCT</b>: most reabsorption (Na, glucose, aa, water). <b>Loop</b>: countercurrent for medullary gradient. <b>DCT/CD</b>: fine-tuning under aldosterone + ADH.</p>' },
  filament: { title:'Sliding Filament', body:'<p>Ca²⁺ from SR → binds troponin C → tropomyosin moves → myosin head binds actin → ATP-driven power stroke. Repeat. Rigor mortis = no ATP to release myosin.</p>' },
  endocrine: { title:'Endocrine Map', body:'<p>Hypothalamus is the master integrator. Anterior pituitary releases tropic hormones (TSH, ACTH, LH/FSH, GH, prolactin). Posterior pituitary stores ADH + oxytocin (made in hypothalamus).</p>' },
  repro: { title:'28-day Cycle', body:'<p><b>Follicular</b>: FSH → follicle → estrogen builds endometrium. <b>Ovulation (~day 14)</b>: LH surge. <b>Luteal</b>: corpus luteum makes progesterone + estrogen, maintains endometrium. If no implant → menses.</p>' },
  ap: { title:'Action Potential', body:'<p>Resting (-70mV) → depolarization (Na⁺ rushes in via VGNa) → peak (+30) → repolarization (K⁺ rushes out via VGK) → hyperpolarization (-90) → return.</p>' },
  vent: { title:'Ventilation', body:'<p>Inspiration: diaphragm contracts → flattens. Volume up → pressure down (Boyle). Air flows in. Expiration: diaphragm relaxes → opposite.</p>' },
  dig: { title:'Digestive Tour', body:'<p>Click each organ to see its enzymes. Most digestion happens in <b>duodenum</b> (pancreatic enzymes + bile). Most absorption in <b>jejunum</b>.</p>' },
  imm: { title:'Immune', body:'<p><b>Innate</b>: fast, non-specific, no memory. <b>Adaptive</b>: slow first, fast second time, specific, memory. Connection: dendritic cells phagocytose → present on MHC II → activate helper T → activate B + cytotoxic T.</p>' },
  blood: { title:'Blood', body:'<p>Plasma 55%, RBCs 45% (hematocrit), buffy coat &lt;1% (WBC + platelets). RBCs: anucleate biconcave, packed with Hb (2α+2β), made under EPO.</p>' },
  neuro: { title:'Neuro', body:'<p>Synapse: AP arrives → VGCa channels open → Ca²⁺ in → vesicles fuse → NT released → binds postsynaptic receptor → ionotropic (fast) or metabotropic (slow).</p>' },
  muscle: { title:'Muscle Types', body:'<p>3 types: skeletal (striated, voluntary, multinucleate), cardiac (striated, involuntary, intercalated discs, branched), smooth (non-striated, involuntary, spindle, single nucleus).</p>' },
  gam: { title:'Gametogenesis', body:'<p>Spermatogenesis: 1 primary spermatocyte → 4 sperm. Oogenesis: 1 primary oocyte → 1 ovum + 3 polar bodies. Females arrest at prophase I until ovulation, metaphase II until fertilization.</p>' },
  // Diversity
  tree: { title:'Tree of Life', body:'<p>3 domains: Bacteria, Archaea, Eukarya. Archaea have unique ether-linked lipids. Eukaryotes evolved from archaeal lineage with α-proteobacterial endosymbiont (mitochondrion).</p>' },
  virus: { title:'Viruses', body:'<p>Viruses aren\'t cells — capsid + nucleic acid (DNA or RNA). Some have lipid envelope. Lytic = destroy host. Lysogenic = integrate as prophage.</p>' },
  bact: { title:'Bacteria', body:'<p>Gram +: thick peptidoglycan, single membrane, susceptible to penicillin. Gram −: thin peptidoglycan + outer membrane with LPS endotoxin. Acid-fast: mycobacteria with mycolic acid.</p>' },
  fungi: { title:'Fungi', body:'<p>Heterotrophic, chitin cell wall, mostly multicellular hyphae. Phyla: Chytrid (only flagellated spores), Zygo (bread mold), Glomero (mycorrhizae), Asco (yeast, penicillium), Basidio (mushrooms, lignin breakdown).</p>' },
  plife: { title:'Plant Lifecycle', body:'<p>Alternation of generations. <b>Trend:</b> gametophyte (n) shrinks across plant evolution; sporophyte (2n) becomes dominant. Bryophytes still gametophyte-dominant.</p>' },
  bplan: { title:'Body Plans', body:'<p>Symmetry: none → radial → bilateral. Layers: diploblast (Cnidaria) → triploblast. Coelom: acoelomate (flatworms) → pseudocoelomate (roundworms) → eucoelomate.</p>' },
  // Devo
  timeline: { title:'Embryo Timeline', body:'<p>Drag the slider through stages. <b>Zygote → cleavage → blastula → gastrula → neurula → organogenesis</b>. Gastrulation establishes 3 germ layers.</p>' },
  germ: { title:'Germ Layers', body:'<p><b>Ectoderm</b>: nervous system + epidermis ("outside"). <b>Endoderm</b>: gut lining + lungs + liver ("inside"). <b>Mesoderm</b>: muscles, bones, kidneys, gonads, blood ("middle").</p>' },
  fert: { title:'Fertilization', body:'<p>Sperm-egg recognition (acrosome reaction) → membrane fusion → cortical reaction prevents polyspermy → activation of egg → meiosis II completes.</p>' },
  // Evolution
  allele: { title:'Allele Sim', body:'<p>HW assumptions: large pop, no mutation, no selection, random mating, no migration. Violations cause evolution. Drift dominates in small pops.</p>' },
  selmode: { title:'Selection Modes', body:'<p>3 patterns of natural selection. <b>Stabilizing</b>: middle wins (birth weight). <b>Directional</b>: one extreme wins (peppered moth). <b>Disruptive</b>: both extremes win (Darwin\'s finches).</p>' },
  spec: { title:'Speciation', body:'<p>Allopatric (geographic isolation, most common) → vicariance or dispersal. Sympatric (same area) → polyploidy in plants, sexual selection, host shift.</p>' },
  evid: { title:'Evidence for Evolution', body:'<p>5 lines: fossil record, comparative anatomy (homology), comparative embryology, biogeography, molecular biology. All converge on common descent.</p>' },
  drift: { title:'Drift Sim', body:'<p>Random sampling causes allele frequencies to wander. Stronger in small populations. <b>Bottleneck</b>: temporary reduction loses diversity. <b>Founder effect</b>: small subset starts new pop.</p>' },
  biome: { title:'Biome Map', body:'<p>Climate (temp + precipitation) determines biome. Rainforest = warm + wet. Tundra = cold + dry. Desert = aridity (often at 30°N/S due to Hadley cells).</p>' },
};
function coachInject() {
  if (document.getElementById('coachFab')) return; // already injected
  const fab = document.createElement('div');
  fab.id = 'coachFab';
  fab.innerHTML = `
    <button id="coachToggle" title="Coach Mode" aria-label="Coach Mode">C</button>
    <div id="coachPanel" class="coach-hidden">
      <div class="coach-header">
        <h4>Coach</h4>
        <button id="coachClose" aria-label="Close">×</button>
      </div>
      <div id="coachContent"></div>
    </div>
  `;
  document.body.appendChild(fab);
  document.getElementById('coachToggle').addEventListener('click', () => {
    const p = document.getElementById('coachPanel');
    const open = !p.classList.contains('coach-hidden');
    if (open) { p.classList.add('coach-hidden'); return; }
    coachUpdateContent();
    p.classList.remove('coach-hidden');
  });
  document.getElementById('coachClose').addEventListener('click', () => {
    document.getElementById('coachPanel').classList.add('coach-hidden');
  });
}
function coachUpdateContent() {
  // Look at currently active tab in any flagship
  const activeTab = document.querySelector('.lab-tabs button.active');
  const tabName = activeTab?.dataset.tab;
  const tip = tabName && COACH_TIPS[tabName];
  let content;
  if (tip) {
    content = `<h5>${tip.title}</h5>${tip.body}`;
  } else {
    // Detect which page we're on
    const pageHints = {
      'engine': '<h5>Bio Engine — Launcher</h5><p>Pick a subject hub or jump straight to a Mock Exam. Your Ace Cards stack up at the bottom — keep up with daily reviews.</p><p><b>Recommended order for a fresh DAT prep:</b> Cell Lab → Genetics → Body Systems → Diversity → Devo → Evolution. Take a baseline mock first.</p>',
      'cell': '<h5>Cell Lab</h5><p>Cell &amp; Molecular is ~33% of DAT bio. Go deep here. The flagship has 16 modules — work through every one at least once.</p>',
      'genetics': '<h5>Genetics Studio</h5><p>~17% of bio. Punnett, pedigrees, HW are mandatory. Mutation sim + epistasis cover the harder questions.</p>',
      'physiology': '<h5>Body Systems Lab</h5><p>~25% of bio. 11 systems to cover. Don\'t neglect endocrine + immune — both heavily tested.</p>',
      'diversity': '<h5>Field Guide</h5><p>~10% of bio. Don\'t skip viruses + bacteria — they show up every test.</p>',
      'devo': '<h5>Embryo Atlas</h5><p>~5% of bio. Smallest section but easy points if you know germ layer derivatives + the protostome/deuterostome split.</p>',
      'evolution': '<h5>Selection Sim</h5><p>~10% of bio. HW math, evidence for evolution, ecology basics. Expect at least 4 questions.</p>',
      'mock': '<h5>Mock Exam</h5><p>Take a full timed mock weekly. Wrong answers automatically spawn Ace Cards. Adaptive weak-topic mode after 1+ mocks taken.</p>',
    };
    const path = location.pathname.toLowerCase();
    let key = 'engine';
    Object.keys(pageHints).forEach(k => { if (path.includes('bio-' + k)) key = k; });
    content = pageHints[key];
  }
  document.getElementById('coachContent').innerHTML = content || '<p>Click a tab to get tailored Coach guidance.</p>';
}
function initCoach() {
  coachInject();
  // Update coach content when tab changes
  document.addEventListener('click', e => {
    if (e.target.closest('.lab-tabs button')) {
      setTimeout(coachUpdateContent, 100);
    }
  });
}

function initTwinsClones() {
  if (!document.getElementById('twinsBody')) return;
  document.getElementById('twinsBody').innerHTML = `
    <svg viewBox="0 0 900 460" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;background:linear-gradient(180deg,#fbf6e9 0%,#f0e9d6 100%);border-radius:10px">
      <text x="450" y="30" text-anchor="middle" font-size="14" font-weight="700" letter-spacing="0.16em" fill="#1B3A2D">TWINS — types and timing</text>
      <g transform="translate(40, 70)">
        <rect width="380" height="160" fill="#fff" stroke="#5FA874" stroke-width="2.5" rx="8"/>
        <text x="190" y="22" text-anchor="middle" font-size="13" font-weight="700" fill="#5FA874">MONOZYGOTIC (identical)</text>
        <circle cx="60" cy="80" r="22" fill="#5FA874" stroke="#1B3A2D" stroke-width="2"/>
        <text x="60" y="84" text-anchor="middle" font-size="9" font-weight="700" fill="#fff">1 zygote</text>
        <line x1="82" y1="80" x2="120" y2="80" stroke="#1B3A2D" stroke-width="2"/>
        <circle cx="160" cy="55" r="20" fill="#5FA874" stroke="#1B3A2D" stroke-width="2"/>
        <circle cx="160" cy="105" r="20" fill="#5FA874" stroke="#1B3A2D" stroke-width="2"/>
        <text x="60" y="120" text-anchor="middle" font-size="9" fill="#1B3A2D">splits</text>
        <text x="200" y="80" font-size="10" font-weight="700" fill="#1B3A2D">→ same DNA, same sex</text>
        <text x="20" y="148" font-size="10" fill="#1B3A2D">~1/250 pregnancies. Worldwide constant rate (genetics-independent).</text>
      </g>
      <g transform="translate(480, 70)">
        <rect width="380" height="160" fill="#fff" stroke="#C25B3F" stroke-width="2.5" rx="8"/>
        <text x="190" y="22" text-anchor="middle" font-size="13" font-weight="700" fill="#C25B3F">DIZYGOTIC (fraternal)</text>
        <circle cx="60" cy="55" r="20" fill="#C25B3F" stroke="#1B3A2D" stroke-width="2"/>
        <text x="60" y="59" text-anchor="middle" font-size="8" font-weight="700" fill="#fff">zygote 1</text>
        <circle cx="60" cy="105" r="20" fill="#a378a5" stroke="#1B3A2D" stroke-width="2"/>
        <text x="60" y="109" text-anchor="middle" font-size="8" font-weight="700" fill="#fff">zygote 2</text>
        <text x="100" y="80" font-size="10" font-weight="700" fill="#1B3A2D">→ different DNA, like normal siblings</text>
        <text x="20" y="148" font-size="10" fill="#1B3A2D">~1/30 (varies by genetics, age, IVF). 2 eggs, 2 sperm.</text>
      </g>
      <g transform="translate(40, 250)">
        <rect width="820" height="200" fill="#fff" stroke="#1B3A2D" stroke-width="1.5" rx="8"/>
        <text x="20" y="24" font-size="12" font-weight="700" fill="#1B3A2D">MONOZYGOTIC SUBTYPES — depends on WHEN the zygote splits</text>
        <text x="20" y="46" font-size="10" font-weight="700" fill="#1B3A2D">Day 1-3 (before morula compacts):</text>
        <text x="350" y="46" font-size="10" fill="#1B3A2D">DI/DI — separate placentas + amniotic sacs (33%)</text>
        <text x="20" y="64" font-size="10" font-weight="700" fill="#1B3A2D">Day 4-8 (after blastocyst forms):</text>
        <text x="350" y="64" font-size="10" fill="#1B3A2D">MO/DI — shared placenta, separate sacs (66%)</text>
        <text x="20" y="82" font-size="10" font-weight="700" fill="#1B3A2D">Day 8-13 (amnion already formed):</text>
        <text x="350" y="82" font-size="10" fill="#1B3A2D">MO/MO — shared placenta + sac (1% — high-risk)</text>
        <text x="20" y="100" font-size="10" font-weight="700" fill="#C25B3F">Day 13+:</text>
        <text x="350" y="100" font-size="10" fill="#1B3A2D">incomplete split → CONJOINED twins (very rare)</text>
        <text x="20" y="130" font-size="11" font-weight="700" fill="#1B3A2D">CLONING (artificial monozygotic)</text>
        <text x="20" y="148" font-size="10" fill="#1B3A2D">SCNT (somatic cell nuclear transfer): nucleus from somatic cell into enucleated egg → activate → develops as clone of nucleus donor.</text>
        <text x="20" y="164" font-size="10" fill="#1B3A2D">Famous: Dolly the sheep (1996). Has been done in many mammals. Failure rate is high; clones often have epigenetic + telomere issues.</text>
        <text x="20" y="184" font-size="10" font-weight="700" fill="#5FA874">In humans, reproductive cloning is banned in most jurisdictions; therapeutic cloning (for stem cells) varies.</text>
      </g>
    </svg>
  `;
}

